    DropdownItem DropdownItemAt(POINT point) const {
        if (!dropdownOpen_) return DropdownItem::None;
        const RECT bounds = GetDropdownBounds();
        if (!PtInRect(&bounds, point)) return DropdownItem::None;
        const int rowHeight = MulDiv(38, GetDpiForWindow(window_), 96);
        int top = bounds.top + MulDiv(4, GetDpiForWindow(window_), 96);
        const int separatorGap = MulDiv(9, GetDpiForWindow(window_), 96);
        const auto hit = [&](DropdownItem item) {
            const bool contains = point.y >= top && point.y < top + rowHeight;
            top += rowHeight;
            return contains ? item : DropdownItem::None;
        };
        DropdownItem item = hit(DropdownItem::OpenFile); if (item != DropdownItem::None) return item;
        item = hit(DropdownItem::Settings); if (item != DropdownItem::None) return item;
        top += separatorGap;
        item = hit(DropdownItem::QuickTour); if (item != DropdownItem::None) return item;
        item = hit(DropdownItem::KeyboardShortcuts); if (item != DropdownItem::None) return item;
        top += separatorGap;
        item = hit(DropdownItem::Help); if (item != DropdownItem::None) return item;
        item = hit(DropdownItem::Feedback); if (item != DropdownItem::None) return item;
        item = hit(DropdownItem::About); if (item != DropdownItem::None) return item;
        top += separatorGap;
        return hit(DropdownItem::Close);
    }
    void SetDropdownHover(DropdownItem item) {
        if (dropdownHovered_ == item) return;
        dropdownHovered_ = item;
        InvalidateRect(window_, nullptr, FALSE);
    }
    void SetDropdownPressed(DropdownItem item) {
        dropdownPressed_ = item;
        InvalidateRect(window_, nullptr, FALSE);
    }
    DropdownItem PressedDropdownItem() const { return dropdownPressed_; }
    void ClearDropdownPressed(bool invalidate = true) {
        if (dropdownPressed_ == DropdownItem::None) return;
        dropdownPressed_ = DropdownItem::None;
        if (invalidate) InvalidateRect(window_, nullptr, FALSE);
    }
    void InvokeDropdownItem(DropdownItem item) {
        const bool openingFile = item == DropdownItem::OpenFile;
        DismissDropdown(!openingFile);
        if (openingFile) OpenFile();
        else if (item == DropdownItem::Settings) ShowOverlay(OverlayKind::Settings);
        else if (item == DropdownItem::QuickTour) StartTutorial();
        else if (item == DropdownItem::KeyboardShortcuts) ShowOverlay(OverlayKind::KeyboardShortcuts);
        else if (item == DropdownItem::Help) ShowOverlay(OverlayKind::Help);
        else if (item == DropdownItem::About) ShowOverlay(OverlayKind::About);
        else if (item == DropdownItem::Feedback) ShowOverlay(OverlayKind::Feedback);
        else if (item == DropdownItem::Close) SendMessageW(window_, WM_SYSCOMMAND, SC_CLOSE, 0);
    }
    void OpenFile() {
        CancelVideoAutoPlayNextCountdown(false);
        ComPtr<IFileOpenDialog> dialog;
        if (FAILED(CoCreateInstance(CLSID_FileOpenDialog, nullptr, CLSCTX_INPROC_SERVER, IID_PPV_ARGS(&dialog)))) {
            InvalidateRect(window_, nullptr, FALSE);
            return;
        }
        static const COMDLG_FILTERSPEC filters[] = {
            { L"Supported files", L"*.jpg;*.jpeg;*.png;*.bmp;*.gif;*.tif;*.tiff;*.ico;*.webp;*.heic;*.heif;*.avif;*.dng;*.cr2;*.cr3;*.nef;*.arw;*.raf;*.mp4;*.mov;*.mkv;*.stl;*.3mf" },
            { L"All files", L"*.*" },
        };
        dialog->SetFileTypes(ARRAYSIZE(filters), filters);
        dialog->SetFileTypeIndex(1);
        dialog->SetTitle(L"Open Image");
        const HRESULT show = dialog->Show(window_);
        if (FAILED(show)) { InvalidateRect(window_, nullptr, FALSE); return; }
        ComPtr<IShellItem> item;
        PWSTR path = nullptr;
        if (SUCCEEDED(dialog->GetResult(&item)) && SUCCEEDED(item->GetDisplayName(SIGDN_FILESYSPATH, &path))) {
            LoadContent(path, true);
            CoTaskMemFree(path);
        }
        InvalidateRect(window_, nullptr, FALSE);
    }
    bool HasImage() const { return source_ != nullptr; }
    bool ModelActive() const { return contentKind_ == ContentKind::Model3D && modelViewport_.Active(); }
    bool VideoActive() const { return contentKind_ == ContentKind::Video2D && videoPlayer_.Active(); }
    bool VideoUserPlaybackActive() const { return videoPlayer_.Playing() && !videoStepHoldTransportActive_; }
    void ToggleVideoPlayPause() {
        if (!VideoActive()) return;
        CancelVideoAutoPlayNextCountdown();
        StopVideoStepHold();
        videoPlayer_.TogglePlayPause();
        if (videoPlayer_.Playing()) videoPausedSeekRefreshPending_ = false;
        ShowVideoControls();
        ScheduleVideoPlaybackTimer();
        if (!videoPlayer_.Playing()) videoPlayer_.FlushFramePacingDiagnostics();
        InvalidateRect(window_, nullptr, FALSE);
    }
    void StopVideoStepHold() {
        KillTimer(window_, kVideoStepHoldTimer);
        const bool temporaryTransport = videoStepHoldTransportActive_;
        videoStepHoldTransportActive_ = false;
        if (temporaryTransport && videoPlayer_.Active()) {
            StopVideoPlaybackScheduler();
            videoPlayer_.EndTemporaryPlayback();
        }
        if (videoStepHoldAudioSuppressed_ && videoPlayer_.Active()) videoPlayer_.SetMuted(videoMuted_);
        videoStepHoldAudioSuppressed_ = false;
        videoStepHoldDirection_ = 0;
        videoStepHoldActive_ = false;
        videoStepHoldSeekInFlight_ = false;
        videoStepHoldAnchorSeconds_ = 0.0;
        videoStepHoldDurationSeconds_ = 0.0;
        videoStepHoldStartQpc_ = 0;
        videoStepHoldQpcFrequency_ = 0;
    }
    bool BeginVideoStepHoldTransport() {
        if (!videoStepHoldDirection_ || !VideoActive() || videoPlayer_.Playing()) return false;
        const double rate = videoStepHoldDirection_ < 0 ? -1.0 : 1.0;
        if (rate < 0.0 && !videoPlayer_.SupportsNegativePlaybackRate()) return false;
        if (!videoPlayer_.SetMuted(true)) return false;
        videoStepHoldAudioSuppressed_ = true;
        if (!videoPlayer_.BeginTemporaryPlayback(rate)) {
            videoPlayer_.SetMuted(videoMuted_);
            videoStepHoldAudioSuppressed_ = false;
            return false;
        }
        videoStepHoldTransportActive_ = true;
        videoPausedSeekRefreshPending_ = false;
        ScheduleVideoPlaybackTimer(true);
        return true;
    }
    void BeginReverseVideoStepHoldSeekFallback() {
        LARGE_INTEGER now{};
        if (!QueryPerformanceCounter(&now) || videoStepHoldQpcFrequency_ <= 0) { StopVideoStepHold(); return; }
        videoStepHoldActive_ = true;
        videoStepHoldStartQpc_ = now.QuadPart;
        SetTimer(window_, kVideoStepHoldTimer, kVideoStepHoldIntervalMs, nullptr);
    }
    bool IssueVideoStepHoldSeek() {
        if (!videoStepHoldDirection_ || videoStepHoldSeekInFlight_ || !VideoActive() || videoPlayer_.Playing()) return false;
        const double target = std::clamp(videoStepHoldDesiredSeconds_, 0.0, videoStepHoldDurationSeconds_);
        if (std::abs(target - videoStepHoldLastIssuedSeconds_) < 0.0005) return false;
        if (!videoPlayer_.Seek(target)) return false;
        videoStepHoldLastIssuedSeconds_ = target;
        videoStepHoldSeekInFlight_ = true;
        videoScrubSeconds_ = target;
        videoPausedSeekRefreshPending_ = true;
        return true;
    }
    void CompleteVideoStepHoldSeek() {
        if (!videoStepHoldSeekInFlight_) return;
        videoStepHoldSeekInFlight_ = false;
        videoPausedSeekRefreshPending_ = true;
        videoPlayer_.UpdateFrame(VideoPlayer::FrameAcquisitionReason::Seek);
        if (videoStepHoldDirection_ < 0 && !videoStepHoldTransportActive_) {
            IssueVideoStepHoldSeek();
        }
        InvalidateRect(window_, nullptr, FALSE);
    }
    bool BeginVideoStepHold(int direction) {
        if (!VideoActive() || !direction) return false;
        StopVideoStepHold();
        const bool initialSeekInFlight = NudgeVideoPosition(direction);
        if (!VideoActive() || videoPlayer_.Playing()) return false;
        double current = 0.0, duration = 0.0;
        if (!videoPlayer_.GetPlaybackTimes(current, duration)) return false;
        LARGE_INTEGER frequency{};
        if (!QueryPerformanceFrequency(&frequency) || frequency.QuadPart <= 0) return false;
        videoStepHoldDirection_ = direction < 0 ? -1 : 1;
        videoStepHoldAnchorSeconds_ = videoPausedSeekRefreshPending_ ? videoScrubSeconds_ : current;
        videoStepHoldDurationSeconds_ = duration;
        videoStepHoldDesiredSeconds_ = videoStepHoldAnchorSeconds_;
        videoStepHoldLastIssuedSeconds_ = videoStepHoldAnchorSeconds_;
        videoStepHoldSeekInFlight_ = initialSeekInFlight;
        videoStepHoldQpcFrequency_ = frequency.QuadPart;
        SetTimer(window_, kVideoStepHoldTimer, kVideoStepHoldThresholdMs, nullptr);
        ShowVideoControls();
        return true;
    }
    void UpdateVideoStepHold() {
        KillTimer(window_, kVideoStepHoldTimer);
        if (!videoStepHoldDirection_ || !VideoActive()) { StopVideoStepHold(); return; }
        if (!videoStepHoldActive_) {
            videoStepHoldActive_ = true;
            if (videoStepHoldDirection_ > 0 || videoPlayer_.SupportsNegativePlaybackRate()) {
                if (!BeginVideoStepHoldTransport()) {
                    if (videoStepHoldDirection_ < 0) BeginReverseVideoStepHoldSeekFallback();
                    else StopVideoStepHold();
                }
                return;
            }
            BeginReverseVideoStepHoldSeekFallback();
            return;
        }
        if (videoStepHoldTransportActive_) return;
        if (videoPlayer_.Playing()) { StopVideoStepHold(); return; }
        LARGE_INTEGER now{};
        if (!QueryPerformanceCounter(&now) || videoStepHoldQpcFrequency_ <= 0) { StopVideoStepHold(); return; }
        const double elapsedSeconds = static_cast<double>(now.QuadPart - videoStepHoldStartQpc_) / static_cast<double>(videoStepHoldQpcFrequency_);
        const double target = std::clamp(videoStepHoldAnchorSeconds_ + videoStepHoldDirection_ * elapsedSeconds, 0.0, videoStepHoldDurationSeconds_);
        videoStepHoldDesiredSeconds_ = target;
        IssueVideoStepHoldSeek();
        InvalidateRect(window_, nullptr, FALSE);
        if (target > 0.0 && target < videoStepHoldDurationSeconds_)
            SetTimer(window_, kVideoStepHoldTimer, kVideoStepHoldIntervalMs, nullptr);
    }
    bool NudgeVideoPosition(int direction) {
        if (!VideoActive() || !direction) return false;
        CancelVideoAutoPlayNextCountdown();
        if (videoPlayer_.Playing()) {
            ToggleVideoPlayPause();
            videoPausedSeekRefreshPending_ = false;
            if (videoPlayer_.Playing()) return false;
        }
        double current = 0.0, duration = 0.0;
        if (!videoPlayer_.GetPlaybackTimes(current, duration)) return false;
        float framesPerSecond = 0.0f;
        const double stepSeconds = videoPlayer_.TryGetFramesPerSecond(framesPerSecond) && std::isfinite(framesPerSecond) && framesPerSecond >= 1.0f && framesPerSecond <= 240.0f
            ? 1.0 / static_cast<double>(framesPerSecond) : 1.0 / 30.0;
        const double anchor = videoPausedSeekRefreshPending_ ? videoScrubSeconds_ : current;
        videoScrubSeconds_ = std::clamp(anchor + direction * stepSeconds, 0.0, duration);
        const bool seekStarted = videoPlayer_.Seek(videoScrubSeconds_);
        if (seekStarted && !videoPlayer_.Playing()) videoPausedSeekRefreshPending_ = true;
        ShowVideoControls();
        InvalidateRect(window_, nullptr, FALSE);
        return seekStarted && !videoPlayer_.Playing();
    }
    bool VideoAdjustmentsPanelAboveControls() const {
        if (!VideoAdjustmentsPanelVisible()) return false;
        const UINT dpi = GetDpiForWindow(window_);
        const int clearance = MulDiv(8, dpi, 96);
        const VideoAdjustmentsPanelLayout normalTarget = GetVideoZoomHudAdjustmentsPanelTargetLayout();
        const RECT controls = GetVideoControlsLayout(false).island;
        const RECT expandedControls{ controls.left - clearance, controls.top - clearance, controls.right + clearance, controls.bottom + clearance };
        const auto intersects = [&](const RECT& bounds) {
            return bounds.left < expandedControls.right && bounds.right > expandedControls.left &&
                bounds.top < expandedControls.bottom && bounds.bottom > expandedControls.top;
        };
        const AdjustmentPanelLipLayout lip = GetAdjustmentPanelLipLayout(normalTarget);
        return intersects(normalTarget.panel) || (lip.active && intersects(lip.bounds));
    }
    VideoControlsLayout GetVideoControlsLayout(bool) const {
        const RECT canvas = ModelCanvasBounds();
        const UINT dpi = GetDpiForWindow(window_);
        const int margin = MulDiv(16, dpi, 96);
        const int bottomGap = MulDiv(24, dpi, 96);
        const int zoomHudClearance = MulDiv(12, dpi, 96);
        const int height = MulDiv(84, dpi, 96);
        const int compactWidth = MulDiv(420, dpi, 96);
        const int preferredWidth = MulDiv(540, dpi, 96);
        const int sideClearance = MulDiv(110, dpi, 96);
        const LONG availableWidth = std::max(1L, canvas.right - canvas.left - margin * 2);
        const int responsiveWidth = static_cast<int>(canvas.right - canvas.left) - sideClearance * 2;
        const int width = std::min(static_cast<int>(availableWidth), std::clamp(responsiveWidth, compactWidth, preferredWidth));
        const int centeredLeft = static_cast<int>(canvas.left + (canvas.right - canvas.left - width) / 2);
        const int left = centeredLeft;
        const bool zoomHudAtBottom = zoomHudPosition_ == ZoomHudPosition::BottomLeft || zoomHudPosition_ == ZoomHudPosition::BottomRight;
        const LONG preferredTop = canvas.bottom - bottomGap - height;
        const LONG maximumTop = zoomHudAtBottom ? GetVideoZoomHudLayout().combined.top - zoomHudClearance - height : preferredTop;
        const int top = static_cast<int>(std::max(canvas.top, std::min(preferredTop, maximumTop)));
        const int padding = std::min(MulDiv(10, dpi, 96), std::max(2, width / 24));
        const int timelineHeight = MulDiv(28, dpi, 96);
        const int rowGap = std::min(MulDiv(5, dpi, 96), std::max(2, height / 16));
        const int buttonWidth = std::min({ MulDiv(32, dpi, 96), std::max(MulDiv(24, dpi, 96), height - padding * 2 - timelineHeight - rowGap), std::max(MulDiv(24, dpi, 96), width / 10) });
        const int gap = std::min(MulDiv(8, dpi, 96), std::max(3, width / 80));
        const int minimumTrackWidth = MulDiv(40, dpi, 96);
        const int maximumTimeWidth = std::max(MulDiv(16, dpi, 96), (width - padding * 2 - gap * 2 - minimumTrackWidth) / 2);
        const int timeWidth = std::min(MulDiv(48, dpi, 96), maximumTimeWidth);
        const int currentLeft = left + padding;
        const int durationRight = left + width - padding;
        const int scrubberLeft = currentLeft + timeWidth + gap;
        const int scrubberRight = std::max(scrubberLeft, durationRight - timeWidth - gap);
        const int controlTop = top + padding + timelineHeight + rowGap;
        const int playLeft = left + padding;
        const int stepBackwardLeft = playLeft + buttonWidth + gap;
        const int stepForwardLeft = stepBackwardLeft + buttonWidth + gap;
        const int speedWidth = std::min(MulDiv(46, dpi, 96), std::max(MulDiv(34, dpi, 96), buttonWidth + gap));
        const int fullscreenLeft = left + width - padding - buttonWidth;
        const int speedLeft = fullscreenLeft - gap - speedWidth;
        const int autoPlayNextLeft = speedLeft - gap - buttonWidth;
        const int volumeGroupLeftLimit = stepForwardLeft + buttonWidth + gap;
        const int volumeGroupRightLimit = autoPlayNextLeft - gap;
        const int volumeWidth = std::min(MulDiv(90, dpi, 96), std::max(1, volumeGroupRightLimit - volumeGroupLeftLimit - buttonWidth - gap));
        const int volumeGroupWidth = buttonWidth + gap + volumeWidth;
        const int centeredVolumeGroupLeft = left + (width - volumeGroupWidth) / 2;
        const int muteLeft = std::clamp(centeredVolumeGroupLeft, volumeGroupLeftLimit,
            std::max(volumeGroupLeftLimit, volumeGroupRightLimit - volumeGroupWidth));
        const int volumeLeft = muteLeft + buttonWidth + gap;
        return { { left, top, left + width, top + height },
            { currentLeft, top + padding, currentLeft + timeWidth, top + padding + timelineHeight },
            { scrubberLeft, top + padding, scrubberRight, top + padding + timelineHeight },
            { durationRight - timeWidth, top + padding, durationRight, top + padding + timelineHeight },
            { playLeft, controlTop, playLeft + buttonWidth, controlTop + buttonWidth },
            { stepBackwardLeft, controlTop, stepBackwardLeft + buttonWidth, controlTop + buttonWidth },
            { stepForwardLeft, controlTop, stepForwardLeft + buttonWidth, controlTop + buttonWidth },
            { muteLeft, controlTop, muteLeft + buttonWidth, controlTop + buttonWidth },
            { volumeLeft, controlTop, volumeLeft + volumeWidth, controlTop + buttonWidth },
            { autoPlayNextLeft, controlTop, autoPlayNextLeft + buttonWidth, controlTop + buttonWidth },
            { speedLeft, controlTop, speedLeft + speedWidth, controlTop + buttonWidth },
            { fullscreenLeft, controlTop, fullscreenLeft + buttonWidth, controlTop + buttonWidth } };
    }
    VideoControlsLayout GetVideoControlsLayout() const { return GetVideoControlsLayout(VideoAdjustmentsPanelAboveControls()); }
    bool AnimatedGifActive() const { return gifDecoder_ && gifFrameCount_ > 1 && source_ != nullptr; }
    GifControlsLayout GetGifControlsLayout() const {
        const D2D1_RECT_F imageCanvas = ImageCanvasBounds();
        const RECT canvas{ static_cast<LONG>(imageCanvas.left), static_cast<LONG>(imageCanvas.top), static_cast<LONG>(imageCanvas.right), static_cast<LONG>(imageCanvas.bottom) };
        const UINT dpi = GetDpiForWindow(window_);
        const LONG button = MulDiv(34, dpi, 96), gap = MulDiv(6, dpi, 96), padding = MulDiv(8, dpi, 96);
        const LONG minimumSlider = MulDiv(96, dpi, 96), preferredSlider = MulDiv(156, dpi, 96);
        const LONG availableSlider = std::max(minimumSlider, canvas.right - canvas.left - button * 3 - gap * 3 - padding * 2);
        const LONG sliderWidth = std::min(preferredSlider, availableSlider);
        const LONG width = button * 3 + gap * 3 + sliderWidth + padding * 2;
        const LONG canvasBottomMargin = MulDiv(16, dpi, 96);
        const LONG filmstripClearance = MulDiv(24, dpi, 96);
        // Reserve the filmstrip's canvas space whether it is currently faded in or hidden, so the
        // independent GIF island never shifts when the strip's visibility animation changes.
        const LONG bottom = canvas.bottom - (FilmstripEligible() ? FilmstripHeight() + canvasBottomMargin + filmstripClearance : canvasBottomMargin);
        const LONG top = std::max(canvas.top + padding, bottom - button - padding * 2);
        const LONG left = std::clamp((canvas.left + canvas.right - width) / 2, canvas.left + padding, std::max(canvas.left + padding, canvas.right - padding - width));
        const RECT island{ left, top, left + width, top + button + padding * 2 };
        const LONG buttonTop = island.top + padding;
        return { island, { left + padding, buttonTop, left + padding + button, buttonTop + button },
            { left + padding + button + gap, buttonTop, left + padding + button * 2 + gap, buttonTop + button },
            { left + padding + button * 2 + gap * 2, buttonTop, left + padding + button * 2 + gap * 2 + sliderWidth, buttonTop + button },
            { left + padding + button * 2 + gap * 3 + sliderWidth, buttonTop, left + padding + button * 3 + gap * 3 + sliderWidth, buttonTop + button } };
    }
    float GifFrameSliderThumbX(const GifControlsLayout& layout) const {
        const float radius = static_cast<float>(MulDiv(12, GetDpiForWindow(window_), 96));
        const float left = static_cast<float>(layout.frameSlider.left) + radius;
        const float right = static_cast<float>(layout.frameSlider.right) - radius;
        if (gifFrameCount_ < 2 || right <= left) return (left + right) * 0.5f;
        return left + (right - left) * static_cast<float>(gifFrameIndex_) / static_cast<float>(gifFrameCount_ - 1);
    }
    bool GifFrameSliderThumbContains(const GifControlsLayout& layout, POINT point) const {
        const float radius = static_cast<float>(MulDiv(12, GetDpiForWindow(window_), 96));
        const float dx = static_cast<float>(point.x) - GifFrameSliderThumbX(layout);
        const float dy = static_cast<float>(point.y) - (layout.frameSlider.top + layout.frameSlider.bottom) * 0.5f;
        return dx * dx + dy * dy <= radius * radius;
    }
    UINT GifFrameSliderIndexAt(const GifControlsLayout& layout, POINT point) const {
        if (gifFrameCount_ < 2) return 0;
        const float radius = static_cast<float>(MulDiv(12, GetDpiForWindow(window_), 96));
        const float left = static_cast<float>(layout.frameSlider.left) + radius;
        const float right = static_cast<float>(layout.frameSlider.right) - radius;
        if (right <= left) return 0;
        const float fraction = std::clamp((static_cast<float>(point.x) - left) / (right - left), 0.0f, 1.0f);
        return static_cast<UINT>(std::lround(fraction * static_cast<float>(gifFrameCount_ - 1)));
    }
    ButtonKind GifControlAt(POINT point) const {
        if (!AnimatedGifActive()) return ButtonKind::None;
        const GifControlsLayout layout = GetGifControlsLayout();
        if (PtInRect(&layout.playPause, point)) return ButtonKind::GifPlayPause;
        if (PtInRect(&layout.stepBackward, point)) return ButtonKind::GifStepBackward;
        if (PtInRect(&layout.stepForward, point)) return ButtonKind::GifStepForward;
        return ButtonKind::None;
    }
    bool GifControlsContains(POINT point) const {
        if (!AnimatedGifActive()) return false;
        const RECT island = GetGifControlsLayout().island;
        return PtInRect(&island, point) != FALSE;
    }
    VideoPlaybackSpeedPanelLayout GetVideoPlaybackSpeedPanelLayout() const {
        const VideoControlsLayout controls = GetVideoControlsLayout();
        const UINT dpi = GetDpiForWindow(window_);
        const int gap = MulDiv(8, dpi, 96);
        const int rowHeight = MulDiv(29, dpi, 96);
        const int width = MulDiv(90, dpi, 96);
        const int height = rowHeight * static_cast<int>(kVideoPlaybackRatePercents.size()) + MulDiv(8, dpi, 96);
        const LONG right = controls.playbackSpeed.right;
        const LONG left = right - width;
        const LONG bottom = controls.island.top - gap;
        const LONG top = bottom - height;
        std::array<RECT, kVideoPlaybackRatePercents.size()> rates{};
        for (size_t index = 0; index < rates.size(); ++index) {
            const LONG rowTop = top + MulDiv(4, dpi, 96) + static_cast<LONG>(index) * rowHeight;
            rates[index] = { left + MulDiv(4, dpi, 96), rowTop, right - MulDiv(4, dpi, 96), rowTop + rowHeight };
        }
        return { { left, top, right, bottom }, rates };
    }
    VideoAdjustmentsPanelLayout MakeVideoAdjustmentsPanelLayout(RECT panel, bool aboveControls) const {
        const UINT dpi = GetDpiForWindow(window_);
        const LONG left = panel.left;
        const LONG right = panel.right;
        const LONG top = panel.top;
        const LONG bottom = panel.bottom;
        const int labelWidth = MulDiv(70, dpi, 96);
        const int valueWidth = MulDiv(38, dpi, 96);
        const int rowHeight = MulDiv(32, dpi, 96);
        const int sliderLeft = left + labelWidth;
        const int panelPadding = MulDiv(12, dpi, 96);
        const int sliderRight = right - valueWidth - panelPadding;
        std::array<RECT, 7> sliders{};
        for (int index = 0; index < 7; ++index) {
            const int y = top + MulDiv(16, dpi, 96) + index * rowHeight;
            sliders[index] = { sliderLeft, y, sliderRight, y + MulDiv(20, dpi, 96) };
        }
        const int footerGap = MulDiv(5, dpi, 96);
        const int autoButtonWidth = MulDiv(42, dpi, 96);
        const int userButtonWidth = MulDiv(38, dpi, 96);
        const int buttonHeight = MulDiv(30, dpi, 96);
        const int originalButtonWidth = buttonHeight;
        const int saveButtonWidth = MulDiv(42, dpi, 96);
        const int resetButtonWidth = MulDiv(44, dpi, 96);
        const int buttonBottom = bottom - panelPadding;
        const RECT autoButton{ left + panelPadding, buttonBottom - buttonHeight, left + panelPadding + autoButtonWidth, buttonBottom };
        const RECT original{ autoButton.right + footerGap, buttonBottom - buttonHeight, autoButton.right + footerGap + originalButtonWidth, buttonBottom };
        const RECT user{ original.right + footerGap, buttonBottom - buttonHeight, original.right + footerGap + userButtonWidth, buttonBottom };
        const RECT save{ user.right + footerGap, buttonBottom - buttonHeight, user.right + footerGap + saveButtonWidth, buttonBottom };
        const RECT reset{ right - panelPadding - resetButtonWidth, buttonBottom - buttonHeight, right - panelPadding, buttonBottom };
        return { panel, sliders, autoButton, user, save, original, reset, aboveControls };
    }
    RECT AdjustmentPanelRevealBounds(const VideoAdjustmentsPanelLayout& panel, float reveal) const {
        RECT bounds = panel.panel;
        const float progress = std::clamp(reveal, 0.0f, 1.0f);
        bounds.top = static_cast<LONG>(std::lround(bounds.bottom + (bounds.top - bounds.bottom) * progress));
        return bounds;
    }
    float AdjustmentPanelPresentationOpacity(float reveal) const {
        return 0.25f + 0.75f * std::clamp(reveal, 0.0f, 1.0f);
    }
    VideoAdjustmentsPanelLayout GetVideoZoomHudAdjustmentsPanelTargetLayout() const {
        return GetImageAdjustmentsPanelTargetLayout();
    }
    VideoAdjustmentsPanelLayout GetVideoAdjustmentsPanelTargetLayout() const {
        const VideoAdjustmentsPanelLayout normal = GetImageAdjustmentsPanelTargetLayout();
        if (!VideoAdjustmentsPanelAboveControls()) return normal;
        const AdjustmentPanelLipLayout lip = GetAdjustmentPanelLipLayout(normal);
        const LONG bottom = lip.active ? lip.bounds.bottom : normal.panel.bottom;
        const RECT controls = GetVideoControlsLayout(false).island;
        const LONG left = controls.left + (controls.right - controls.left - (normal.panel.right - normal.panel.left)) / 2;
        auto target = OffsetVideoAdjustmentsPanelLayout(normal, left - normal.panel.left, controls.top - bottom);
        target.aboveControls = true;
        return target;
    }
    bool VideoAdjustmentsPanelMotionActive() const {
        return videoAdjustmentsPanelMotion_ != VideoAdjustmentsPanelMotion::None;
    }
    VideoAdjustmentsPanelLayout OffsetVideoAdjustmentsPanelLayout(const VideoAdjustmentsPanelLayout& layout, LONG x, LONG y) const {
        RECT panel = layout.panel;
        OffsetRect(&panel, x, y);
        return MakeVideoAdjustmentsPanelLayout(panel, layout.aboveControls);
    }
    VideoAdjustmentsPanelLayout VideoAdjustmentsPanelAttachmentLayout(const VideoAdjustmentsPanelLayout& target) const {
        const LONG offset = MulDiv(16, GetDpiForWindow(window_), 96);
        return OffsetVideoAdjustmentsPanelLayout(target, 0, offset);
    }
    void StopVideoAdjustmentsPanelMotion() {
        videoAdjustmentsPanelMotion_ = VideoAdjustmentsPanelMotion::None;
        KillTimer(window_, kVideoAdjustmentsPlacementTimer);
    }
    RECT VideoAdjustmentsPanelMotionRect(float progress) const {
        const RECT start = videoAdjustmentsPanelPlacementStartLayout_.panel;
        const RECT target = videoAdjustmentsPanelPlacementTargetLayout_.panel;
        if (videoAdjustmentsPanelPlacementTargetLayout_.aboveControls) {
            // Dock directly: one monotonic flight, with no overshoot or settling leg.
            const float phase = SmoothTransitionProgress(progress);
            const auto coordinate = [phase](LONG from, LONG to) {
                return static_cast<LONG>(std::lround(from + (to - from) * phase));
            };
            return { coordinate(start.left, target.left), coordinate(start.top, target.top),
                coordinate(start.right, target.right), coordinate(start.bottom, target.bottom) };
        }
        const float startWidth = static_cast<float>(start.right - start.left), startHeight = static_cast<float>(start.bottom - start.top);
        const float targetWidth = static_cast<float>(target.right - target.left), targetHeight = static_cast<float>(target.bottom - target.top);
        const float startX = (start.left + start.right) * 0.5f, startY = (start.top + start.bottom) * 0.5f;
        const float targetX = (target.left + target.right) * 0.5f, targetY = (target.top + target.bottom) * 0.5f;
        const float directionX = targetX - startX, directionY = targetY - startY;
        const float distance = std::sqrt(directionX * directionX + directionY * directionY);
        const float overshoot = std::min(static_cast<float>(MulDiv(5, GetDpiForWindow(window_), 96)), distance * 0.10f);
        float centerX = targetX, centerY = targetY, width = targetWidth, height = targetHeight;
        if (progress < 0.82f && distance > 0.01f) {
            const float phase = VideoAdjustmentsPlacementProgress(progress / 0.82f);
            const float endX = targetX + directionX / distance * overshoot;
            const float endY = targetY + directionY / distance * overshoot;
            const float curve = std::min(static_cast<float>(MulDiv(10, GetDpiForWindow(window_), 96)), distance * 0.08f);
            const float bend = videoAdjustmentsPanelPlacementStartLayout_.aboveControls ? -curve : curve;
            const float controlX = (startX + endX) * 0.5f - directionY / distance * bend;
            const float controlY = (startY + endY) * 0.5f + directionX / distance * bend;
            const float inverse = 1.0f - phase;
            centerX = inverse * inverse * startX + 2.0f * inverse * phase * controlX + phase * phase * endX;
            centerY = inverse * inverse * startY + 2.0f * inverse * phase * controlY + phase * phase * endY;
            width = startWidth + (targetWidth - startWidth) * phase;
            height = startHeight + (targetHeight - startHeight) * phase;
        } else if (progress < 1.0f && distance > 0.01f) {
            const float phase = SmoothTransitionProgress((progress - 0.82f) / 0.18f);
            const float overshootX = targetX + directionX / distance * overshoot;
            const float overshootY = targetY + directionY / distance * overshoot;
            centerX = overshootX + (targetX - overshootX) * phase;
            centerY = overshootY + (targetY - overshootY) * phase;
        }
        const LONG left = static_cast<LONG>(std::lround(centerX - width * 0.5f));
        const LONG top = static_cast<LONG>(std::lround(centerY - height * 0.5f));
        return { left, top, left + static_cast<LONG>(std::lround(width)), top + static_cast<LONG>(std::lround(height)) };
    }
    RECT VideoAdjustmentsPanelOpenCloseMotionRect(float progress) const {
        const RECT start = videoAdjustmentsPanelPlacementStartLayout_.panel;
        const RECT target = videoAdjustmentsPanelPlacementTargetLayout_.panel;
        const float directionX = 0.0f;
        const float directionY = -1.0f;
        const float startX = (start.left + start.right) * 0.5f, startY = (start.top + start.bottom) * 0.5f;
        const float targetX = (target.left + target.right) * 0.5f, targetY = (target.top + target.bottom) * 0.5f;
        float centerX = targetX, centerY = targetY;
        if (videoAdjustmentsPanelMotion_ == VideoAdjustmentsPanelMotion::Opening && progress < 0.82f) {
            const float phase = VideoAdjustmentsPlacementProgress(progress / 0.82f);
            const float overshoot = static_cast<float>(MulDiv(5, GetDpiForWindow(window_), 96));
            centerX = startX + (targetX + directionX * overshoot - startX) * phase;
            centerY = startY + (targetY + directionY * overshoot - startY) * phase;
        } else if (videoAdjustmentsPanelMotion_ == VideoAdjustmentsPanelMotion::Opening && progress < 1.0f) {
            const float phase = SmoothTransitionProgress((progress - 0.82f) / 0.18f);
            const float overshoot = static_cast<float>(MulDiv(5, GetDpiForWindow(window_), 96));
            centerX = targetX + directionX * overshoot * (1.0f - phase);
            centerY = targetY + directionY * overshoot * (1.0f - phase);
        } else if (videoAdjustmentsPanelMotion_ == VideoAdjustmentsPanelMotion::Closing) {
            const float phase = progress * progress * progress;
            centerX = startX + (targetX - startX) * phase;
            centerY = startY + (targetY - startY) * phase;
        }
        const LONG width = target.right - target.left;
        const LONG height = target.bottom - target.top;
        const LONG left = static_cast<LONG>(std::lround(centerX - width * 0.5f));
        const LONG top = static_cast<LONG>(std::lround(centerY - height * 0.5f));
        return { left, top, left + width, top + height };
    }
    void UpdateVideoAdjustmentsPanelPlacementMotion() {
        if (!VideoAdjustmentsPanelMotionActive()) return;
        const ULONGLONG duration = videoAdjustmentsPanelMotion_ == VideoAdjustmentsPanelMotion::Placement ? kVideoAdjustmentsPlacementDurationMs :
            videoAdjustmentsPanelMotion_ == VideoAdjustmentsPanelMotion::Opening ? kVideoAdjustmentsOpenDurationMs : kVideoAdjustmentsCloseDurationMs;
        const float progress = std::min(1.0f, static_cast<float>(GetTickCount64() - videoAdjustmentsPanelPlacementStartedAt_) /
            static_cast<float>(duration));
        if (progress >= 1.0f) {
            videoAdjustmentsPanelPresentedLayout_ = videoAdjustmentsPanelPlacementTargetLayout_;
            StopVideoAdjustmentsPanelMotion();
        } else {
            videoAdjustmentsPanelPresentedLayout_ = MakeVideoAdjustmentsPanelLayout(
                videoAdjustmentsPanelMotion_ == VideoAdjustmentsPanelMotion::Placement ? VideoAdjustmentsPanelMotionRect(progress) :
                VideoAdjustmentsPanelOpenCloseMotionRect(progress), videoAdjustmentsPanelPlacementTargetLayout_.aboveControls);
        }
        if (!VideoActive() && ImageAdjustmentsPanelVisible()) SynchronizeFilmstripAdjustmentAvoidance();
        InvalidateRect(window_, nullptr, FALSE);
    }
    void BeginVideoAdjustmentsPanelPlacementMotion(const VideoAdjustmentsPanelLayout& target) {
        videoAdjustmentsPanelPlacementStartLayout_ = videoAdjustmentsPanelPresentedLayout_;
        videoAdjustmentsPanelPlacementTargetLayout_ = target;
        videoAdjustmentsPanelPlacementStartedAt_ = GetTickCount64();
        videoAdjustmentsPanelMotion_ = VideoAdjustmentsPanelMotion::Placement;
        SetTimer(window_, kVideoAdjustmentsPlacementTimer, 16, nullptr);
    }
    void BeginVideoAdjustmentsPanelOpenMotion(const VideoAdjustmentsPanelLayout& target, bool fromPresentedLayout) {
        videoAdjustmentsPanelPlacementStartLayout_ = fromPresentedLayout ? videoAdjustmentsPanelPresentedLayout_ : VideoAdjustmentsPanelAttachmentLayout(target);
        if (!fromPresentedLayout) videoAdjustmentsPanelPresentedLayout_ = videoAdjustmentsPanelPlacementStartLayout_;
        videoAdjustmentsPanelPlacementTargetLayout_ = target;
        videoAdjustmentsPanelPlacementStartedAt_ = GetTickCount64();
        videoAdjustmentsPanelMotion_ = VideoAdjustmentsPanelMotion::Opening;
        SetTimer(window_, kVideoAdjustmentsPlacementTimer, 16, nullptr);
    }
    void BeginVideoAdjustmentsPanelCloseMotion(const VideoAdjustmentsPanelLayout& target) {
        videoAdjustmentsPanelPlacementStartLayout_ = videoAdjustmentsPanelPresentedLayout_;
        videoAdjustmentsPanelPlacementTargetLayout_ = VideoAdjustmentsPanelAttachmentLayout(target);
        videoAdjustmentsPanelPlacementStartedAt_ = GetTickCount64();
        videoAdjustmentsPanelMotion_ = VideoAdjustmentsPanelMotion::Closing;
        SetTimer(window_, kVideoAdjustmentsPlacementTimer, 16, nullptr);
    }
    void SynchronizeVideoAdjustmentsPanelPresentedLayout(bool animatePlacement = false) {
        if (adjustmentPanelNavigation_.pending) return;
        if (!animationsEnabled_) animatePlacement = false;
        const VideoAdjustmentsPanelLayout target = GetVideoAdjustmentsPanelTargetLayout();
        if (!animatePlacement || videoAdjustmentsDragging_ >= 0) {
            StopVideoAdjustmentsPanelMotion();
            videoAdjustmentsPanelPresentedLayout_ = target;
            return;
        }
        if (VideoAdjustmentsPanelMotionActive()) {
            UpdateVideoAdjustmentsPanelPlacementMotion();
            if (!VideoAdjustmentsPanelMotionActive()) {
                videoAdjustmentsPanelPresentedLayout_ = target;
                return;
            }
            if (videoAdjustmentsPanelMotion_ == VideoAdjustmentsPanelMotion::Closing) {
                if (target.aboveControls != videoAdjustmentsPanelPlacementTargetLayout_.aboveControls)
                    BeginVideoAdjustmentsPanelCloseMotion(target);
                else
                    videoAdjustmentsPanelPlacementTargetLayout_ = VideoAdjustmentsPanelAttachmentLayout(target);
                return;
            }
            if (videoAdjustmentsPanelMotion_ == VideoAdjustmentsPanelMotion::Opening) {
                if (target.aboveControls != videoAdjustmentsPanelPlacementTargetLayout_.aboveControls)
                    BeginVideoAdjustmentsPanelOpenMotion(target, true);
                else
                    videoAdjustmentsPanelPlacementTargetLayout_ = target;
                return;
            }
            if (target.aboveControls != videoAdjustmentsPanelPlacementTargetLayout_.aboveControls)
                BeginVideoAdjustmentsPanelPlacementMotion(target);
            else
                videoAdjustmentsPanelPlacementTargetLayout_ = target;
            return;
        }
        if (!videoAdjustmentsPanelOpen_) {
            videoAdjustmentsPanelPresentedLayout_ = target;
            return;
        }
        if (target.aboveControls != videoAdjustmentsPanelPresentedLayout_.aboveControls)
            BeginVideoAdjustmentsPanelPlacementMotion(target);
        else
            videoAdjustmentsPanelPresentedLayout_ = target;
    }
    const VideoAdjustmentsPanelLayout& GetVideoAdjustmentsPanelPresentedLayout() const {
        return videoAdjustmentsPanelPresentedLayout_;
    }
    bool VideoAdjustmentsPanelContains(POINT point) const {
        if (adjustmentPanelNavigation_.pending || !VideoActive() || !videoAdjustmentsPanelOpen_ ||
            videoAdjustmentsPanelOpacity_ * videoControlsOpacity_ <= 0.05f) return false;
        const VideoAdjustmentsPanelLayout& layout = GetVideoAdjustmentsPanelPresentedLayout();
        const RECT panel = AdjustmentPanelRenderedRevealBounds(layout, videoAdjustmentsPanelOpacity_, GetAdjustmentPanelLipLayout(layout));
        return PtInRect(&panel, point) != FALSE;
    }
    bool VideoAdjustmentsPanelVisible() const {
        return videoAdjustmentsPanelOpen_ || videoAdjustmentsPanelFadeActive_ || videoAdjustmentsPanelOpacity_ > 0.001f;
    }
    bool VideoPlaybackSpeedPanelContains(POINT point) const {
        if (!videoPlaybackSpeedPanelOpen_) return false;
        const RECT panel = GetVideoPlaybackSpeedPanelLayout().panel;
        return PtInRect(&panel, point) != FALSE;
    }
    bool VideoPlaybackSpeedPanelOpen() const { return videoPlaybackSpeedPanelOpen_; }
    void SetVideoPlaybackSpeedPanelOpen(bool open) {
        videoPlaybackSpeedPanelOpen_ = open;
        if (!open) {
            videoControlsPointerOver_ = false;
            SetVideoPlaybackSpeedHover(-1);
        } else SetVideoPlaybackSpeedHover(VideoPlaybackSpeedRateAt(lastMousePoint_));
        ShowVideoControls();
    }
    void SelectVideoPlaybackRate(DWORD percent) {
        if (!IsVideoPlaybackRatePercent(percent)) return;
        const double requested = PlaybackRateFromPercent(percent);
        videoPreferredPlaybackRatePercent_ = percent;
        if (!VideoActive() || videoPlayer_.SetPreferredPlaybackRate(requested)) {
            videoEffectivePlaybackRate_ = VideoActive() ? videoPlayer_.EffectivePlaybackRate() : requested;
            if (VideoActive() && videoPlayer_.Playing()) ScheduleVideoPlaybackTimer(true);
        }
        InvalidateRect(window_, nullptr, FALSE);
    }
    void ApplyVideoAdjustments() {
        videoPlayer_.SetDisplayAdjustments(videoAdjustments_);
        InvalidateRect(window_, nullptr, FALSE);
    }
    void SetVideoAdjustmentsOriginalPreview(bool active) {
        if (videoAdjustmentsOriginalPreviewActive_ == active) return;
        videoAdjustmentsOriginalPreviewActive_ = active;
        videoPlayer_.SetDisplayAdjustmentsBypassed(active);
        InvalidateRect(window_, nullptr, FALSE);
    }
    void SetImageAdjustmentsOriginalPreview(bool active) {
        if (imageAdjustmentsOriginalPreviewActive_ == active) return;
        imageAdjustmentsOriginalPreviewActive_ = active;
        InvalidateRect(window_, nullptr, FALSE);
    }
    bool VideoAdjustmentsPanelOpen() const {
        return adjustmentPanelNavigation_.pending ? VideoActive() && adjustmentPanelNavigation_.open : videoAdjustmentsPanelOpen_;
    }
    void BeginAdjustmentPanelNavigation(const std::wstring& path) {
        auto& held = adjustmentPanelNavigation_;
        if (IsModelPath(path)) { held = {}; return; }
        if (held.pending) { held.path = path; return; }
        if (!VideoActive() && !source_) return;
        const bool video = VideoActive();
        UpdateVideoAdjustmentsPanelPlacementMotion();
        UpdateAdjustmentPanelFade(imageAdjustmentsPanelOpen_, imageAdjustmentsPanelFadeActive_,
            imageAdjustmentsPanelOpacity_, imageAdjustmentsPanelFadeStartOpacity_, imageAdjustmentsPanelFadeStartedAt_);
        UpdateVideoAdjustmentsPanelFade();
        held.open = video ? videoAdjustmentsPanelOpen_ : imageAdjustmentsPanelOpen_;
        held.fadeActive = video ? videoAdjustmentsPanelFadeActive_ : imageAdjustmentsPanelFadeActive_;
        held.opacity = video ? videoAdjustmentsPanelOpacity_ : imageAdjustmentsPanelOpacity_;
        held.fadeStartOpacity = video ? videoAdjustmentsPanelFadeStartOpacity_ : imageAdjustmentsPanelFadeStartOpacity_;
        held.fadeStartedAt = video ? videoAdjustmentsPanelFadeStartedAt_ : imageAdjustmentsPanelFadeStartedAt_;
        held.layout = video ? GetVideoAdjustmentsPanelPresentedLayout() : GetImageAdjustmentsPanelLayout();
        held.lip = GetAdjustmentPanelLipLayout(held.layout);
        held.physicalScale = video ? VideoCurrentScale() * RenderTargetDpi() / 96.0f : PhysicalPixelScale();
        held.overlayOpacity = video ? videoControlsOpacity_ : 1.0f;
        held.values = video ? videoAdjustments_ : imageAdjustments_;
        held.source = video ? videoAdjustmentSource_ : imageAdjustmentSource_;
        held.path = path;
        held.pending = true;
        // Retain the outgoing UI independently of player teardown and superseding opens.
        StopVideoAdjustmentsPanelMotion();
        imageAdjustmentsDragging_ = videoAdjustmentsDragging_ = -1;
        imageAdjustmentThumbGrab_ = videoAdjustmentThumbGrab_ = false;
        SetImageAdjustmentsOriginalPreview(false);
        SetVideoAdjustmentsOriginalPreview(false);
        adjustmentFooterPressed_ = AdjustmentFooterButton::None;
        adjustmentFooterHovered_ = AdjustmentFooterButton::None;
    }
    void CommitAdjustmentPanelNavigation(const std::wstring& path) {
        auto& held = adjustmentPanelNavigation_;
        if (!held.pending || !PathsEqual(fs::path(path), fs::path(held.path)) ||
            !PathsEqual(fs::path(path), fs::path(currentPath_))) return;
        UpdateAdjustmentPanelFade(held.open, held.fadeActive, held.opacity, held.fadeStartOpacity, held.fadeStartedAt);
        const bool video = VideoActive();
        imageAdjustmentsPanelOpen_ = !video && held.open;
        videoAdjustmentsPanelOpen_ = video && held.open;
        imageAdjustmentsPanelFadeActive_ = !video && held.fadeActive;
        videoAdjustmentsPanelFadeActive_ = video && held.fadeActive;
        imageAdjustmentsPanelOpacity_ = !video ? held.opacity : 0.0f;
        videoAdjustmentsPanelOpacity_ = video ? held.opacity : 0.0f;
        imageAdjustmentsPanelFadeStartOpacity_ = videoAdjustmentsPanelFadeStartOpacity_ = held.fadeStartOpacity;
        imageAdjustmentsPanelFadeStartedAt_ = videoAdjustmentsPanelFadeStartedAt_ = held.fadeStartedAt;
        videoAdjustmentsPanelPresentedLayout_ = held.layout;
        held.pending = false;
        if (video) SynchronizeVideoAdjustmentsPanelPresentedLayout(true);
        else {
            imageAdjustmentsPanelTargetLayout_ = GetImageAdjustmentsPanelTargetLayout();
            videoAdjustmentsPanelPresentedLayout_ = imageAdjustmentsPanelTargetLayout_;
            SynchronizeFilmstripAdjustmentAvoidance();
        }
        if (held.fadeActive) SetTimer(window_, kVideoAdjustmentsFadeTimer, 16, nullptr);
    }
    bool PersistentAdjustmentHudVisible() const {
        return adjustmentPanelNavigation_.pending ? adjustmentPanelNavigation_.open :
            VideoActive() ? videoAdjustmentsPanelOpen_ : source_ && imageAdjustmentsPanelOpen_;
    }
    void DrawPersistentAdjustmentHud() {
        if (!zoomHudEnabled_ || !PersistentAdjustmentHudVisible()) return;
        const float physicalScale = adjustmentPanelNavigation_.pending ? adjustmentPanelNavigation_.physicalScale :
            VideoActive() ? VideoCurrentScale() * RenderTargetDpi() / 96.0f : PhysicalPixelScale();
        DrawZoomHud(GetImageZoomHudLayout(), physicalScale, 1.0f, true, true);
    }
    float AdjustmentOverlayOpacity() const {
        return adjustmentPanelNavigation_.pending ? adjustmentPanelNavigation_.overlayOpacity :
            VideoActive() ? videoControlsOpacity_ : 1.0f;
    }
    void DrawAdjustmentOverlays() {
        const float opacity = AdjustmentOverlayOpacity();
        if (opacity <= 0.001f) return;
        // Apply transport auto-hide to the complete assembly, independently of its
        // existing roll/reveal animation and logical open state.
        if (opacity < 0.999f)
            renderTarget_->PushLayer(D2D1::LayerParameters(D2D1::InfiniteRect(), nullptr,
                D2D1_ANTIALIAS_MODE_PER_PRIMITIVE, D2D1::IdentityMatrix(), opacity), nullptr);
        DrawNavigatingAdjustmentPanel();
        DrawPersistentAdjustmentHud();
        if (opacity < 0.999f) renderTarget_->PopLayer();
    }
    float AdjustmentDockFillProgress() const {
        if (adjustmentPanelNavigation_.pending)
            return adjustmentPanelNavigation_.layout.aboveControls ? 1.0f : 0.0f;
        if (!VideoActive()) return 0.0f;
        if (videoAdjustmentsPanelMotion_ == VideoAdjustmentsPanelMotion::Placement) {
            const float start = videoAdjustmentsPanelPlacementStartLayout_.aboveControls ? 1.0f : 0.0f;
            const float target = videoAdjustmentsPanelPlacementTargetLayout_.aboveControls ? 1.0f : 0.0f;
            // Finish the notch fill before the bottom corners begin their docking morph.
            const float progress = SmoothTransitionProgress(std::min(1.0f,
                static_cast<float>(GetTickCount64() - videoAdjustmentsPanelPlacementStartedAt_) /
                (static_cast<float>(kVideoAdjustmentsPlacementDurationMs) * 0.65f)));
            return start + (target - start) * progress;
        }
        return videoAdjustmentsPanelPresentedLayout_.aboveControls ? 1.0f : 0.0f;
    }
    // Join only at the dock, never while the placement animation is in flight.
    bool GetDockedAdjustmentJoin(RECT& foot) const {
        const auto& held = adjustmentPanelNavigation_;
        const auto& panel = held.pending ? held.layout : videoAdjustmentsPanelPresentedLayout_;
        if (!panel.aboveControls || (!held.pending && (!VideoActive() || !VideoAdjustmentsPanelVisible()))) return false;
        if ((held.pending ? held.opacity : videoAdjustmentsPanelOpacity_) <= 0.001f) return false;
        const float controlsOpacity = TransitionOverlayActive() && transitionOverlayHasVideoControls_ ?
            transitionOverlayVideoControlsOpacity_ : videoControlsOpacity_;
        if (controlsOpacity <= 0.001f) return false;
        const auto lip = held.pending ? held.lip : GetAdjustmentPanelLipLayout(panel);
        if (!lip.active) return false;
        foot = lip.bounds;
        foot.right = panel.panel.right; // Fill the docked notch without moving footer controls.
        const RECT controls = GetVideoControlsLayout(false).island;
        const LONG radius = MulDiv(10, GetDpiForWindow(window_), 96);
        return foot.bottom == controls.top && foot.left - radius > controls.left + radius &&
            foot.right + radius < controls.right - radius;
    }
    bool GetAdjustmentDockMorph(RECT& foot, float& progress) const {
        if (GetDockedAdjustmentJoin(foot)) { progress = 1.0f; return true; }
        if (adjustmentPanelNavigation_.pending || !VideoActive() || !VideoAdjustmentsPanelVisible() ||
            videoAdjustmentsPanelMotion_ != VideoAdjustmentsPanelMotion::Placement ||
            !videoAdjustmentsPanelPlacementTargetLayout_.aboveControls) return false;
        const float flight = std::min(1.0f,
            static_cast<float>(GetTickCount64() - videoAdjustmentsPanelPlacementStartedAt_) /
            static_cast<float>(kVideoAdjustmentsPlacementDurationMs));
        if (flight <= 0.70f) return false;
        const auto lip = GetAdjustmentPanelLipLayout(videoAdjustmentsPanelPresentedLayout_);
        if (!lip.active) return false;
        foot = lip.bounds;
        foot.right = videoAdjustmentsPanelPresentedLayout_.panel.right;
        // Only morph toward a dock that has room for the final exposed shoulders.
        const RECT controls = GetVideoControlsLayout(false).island;
        const RECT target = videoAdjustmentsPanelPlacementTargetLayout_.panel;
        const LONG radius = MulDiv(10, GetDpiForWindow(window_), 96);
        if (target.left - radius <= controls.left + radius || target.right + radius >= controls.right - radius) return false;
        progress = SmoothTransitionProgress((flight - 0.70f) / 0.30f);
        return true;
    }
    void DrawNavigatingAdjustmentPanel() {
        DrawAdjustmentDockConnection();
        auto& held = adjustmentPanelNavigation_;
        if (held.pending) {
            if (held.opacity <= 0.001f) return;
            drawingHeldAdjustmentPanel_ = true;
            DrawAdjustmentPanel(held.layout, held.values, held.opacity, held.source, false);
            drawingHeldAdjustmentPanel_ = false;
        } else if (VideoActive() && VideoAdjustmentsPanelVisible()) {
            DrawAdjustmentPanel(GetVideoAdjustmentsPanelPresentedLayout(), videoAdjustments_, videoAdjustmentsPanelOpacity_,
                videoAdjustmentSource_, videoAdjustmentsOriginalPreviewActive_);
        } else if (source_ && TransitionOverlayActive() && ImageAdjustmentsPanelVisible()) {
            DrawAdjustmentPanel(GetImageAdjustmentsPanelLayout(), imageAdjustments_, imageAdjustmentsPanelOpacity_,
                imageAdjustmentSource_, imageAdjustmentsOriginalPreviewActive_);
        }
    }
    bool HeldAdjustmentPanelContains(POINT point) const {
        const auto& held = adjustmentPanelNavigation_;
        if (!held.pending || held.opacity * held.overlayOpacity <= 0.05f) return false;
        const RECT bounds = AdjustmentPanelRenderedRevealBounds(held.layout, held.opacity, held.lip);
        return PtInRect(&bounds, point) != FALSE;
    }
    void SetAdjustmentPanelOpen(bool& panelOpen, bool& fadeActive, float& opacity,
            float& fadeStartOpacity, ULONGLONG& fadeStartedAt, bool open) {
        if (open == panelOpen && !fadeActive) return;
        panelOpen = open;
        if (!animationsEnabled_) {
            fadeActive = false;
            opacity = open ? 1.0f : 0.0f;
            fadeStartOpacity = opacity;
            fadeStartedAt = GetTickCount64();
            if (!imageAdjustmentsPanelFadeActive_ && !videoAdjustmentsPanelFadeActive_)
                KillTimer(window_, kVideoAdjustmentsFadeTimer);
            return;
        }
        fadeStartOpacity = opacity;
        fadeStartedAt = GetTickCount64();
        fadeActive = open ? opacity < 0.999f : opacity > 0.001f;
        if (fadeActive) SetTimer(window_, kVideoAdjustmentsFadeTimer, 16, nullptr);
        else {
            opacity = open ? 1.0f : 0.0f;
            if (!imageAdjustmentsPanelFadeActive_ && !videoAdjustmentsPanelFadeActive_)
                KillTimer(window_, kVideoAdjustmentsFadeTimer);
        }
    }
    bool UpdateAdjustmentPanelFade(bool panelOpen, bool& fadeActive, float& opacity,
            float fadeStartOpacity, ULONGLONG fadeStartedAt) {
        if (!fadeActive) return false;
        const float progress = std::min(1.0f, static_cast<float>(GetTickCount64() - fadeStartedAt) /
            static_cast<float>(kVideoAdjustmentsFadeDurationMs));
        const float eased = VideoAdjustmentsPlacementProgress(progress);
        opacity = panelOpen
            ? fadeStartOpacity + (1.0f - fadeStartOpacity) * eased
            : fadeStartOpacity * (1.0f - eased);
        if (progress >= 1.0f) {
            fadeActive = false;
            opacity = panelOpen ? 1.0f : 0.0f;
        }
        return fadeActive;
    }
    bool UpdateVideoAdjustmentsPanelFade() {
        if (!videoAdjustmentsPanelFadeActive_) return false;
        const ULONGLONG duration = kVideoAdjustmentsFadeDurationMs;
        const float progress = std::min(1.0f, static_cast<float>(GetTickCount64() - videoAdjustmentsPanelFadeStartedAt_) /
            static_cast<float>(duration));
        const float eased = VideoAdjustmentsPlacementProgress(progress);
        videoAdjustmentsPanelOpacity_ = videoAdjustmentsPanelOpen_
            ? videoAdjustmentsPanelFadeStartOpacity_ + (1.0f - videoAdjustmentsPanelFadeStartOpacity_) * eased
            : videoAdjustmentsPanelFadeStartOpacity_ * (1.0f - eased);
        if (progress >= 1.0f) {
            videoAdjustmentsPanelFadeActive_ = false;
            videoAdjustmentsPanelOpacity_ = videoAdjustmentsPanelOpen_ ? 1.0f : 0.0f;
        }
        return videoAdjustmentsPanelFadeActive_;
    }
    void SetVideoAdjustmentsPanelOpen(bool open) {
        if (adjustmentPanelNavigation_.pending) {
            auto& held = adjustmentPanelNavigation_;
            SetAdjustmentPanelOpen(held.open, held.fadeActive, held.opacity, held.fadeStartOpacity, held.fadeStartedAt, open);
            InvalidateRect(window_, nullptr, FALSE);
            return;
        }
        if (open == videoAdjustmentsPanelOpen_ && !videoAdjustmentsPanelFadeActive_) return;
        const bool wasMoving = VideoAdjustmentsPanelMotionActive();
        if (wasMoving) UpdateVideoAdjustmentsPanelPlacementMotion();
        const VideoAdjustmentsPanelLayout closeTarget = !open ? GetVideoAdjustmentsPanelTargetLayout() : VideoAdjustmentsPanelLayout{};
        if (open) videoPlaybackSpeedPanelOpen_ = false;
        videoAdjustmentsDragging_ = -1;
        videoAdjustmentThumbGrab_ = false;
        if (!open && videoAdjustmentsOriginalPreviewActive_) {
            SetVideoAdjustmentsOriginalPreview(false);
            if (GetCapture() == window_) ReleaseCapture();
        }
        if (!open) videoControlsPointerOver_ = false;
        SetAdjustmentPanelOpen(videoAdjustmentsPanelOpen_, videoAdjustmentsPanelFadeActive_,
            videoAdjustmentsPanelOpacity_, videoAdjustmentsPanelFadeStartOpacity_,
            videoAdjustmentsPanelFadeStartedAt_, open);
        StopVideoAdjustmentsPanelMotion();
        videoAdjustmentsPanelPresentedLayout_ = open ? GetVideoAdjustmentsPanelTargetLayout() : closeTarget;
        ShowVideoControls();
    }
    void UpdateAdjustmentPanelsFade() {
        auto& held = adjustmentPanelNavigation_;
        const bool heldActive = held.pending && UpdateAdjustmentPanelFade(held.open, held.fadeActive,
            held.opacity, held.fadeStartOpacity, held.fadeStartedAt);
        const bool imageActive = UpdateAdjustmentPanelFade(imageAdjustmentsPanelOpen_, imageAdjustmentsPanelFadeActive_,
            imageAdjustmentsPanelOpacity_, imageAdjustmentsPanelFadeStartOpacity_, imageAdjustmentsPanelFadeStartedAt_);
        const bool videoActive = UpdateVideoAdjustmentsPanelFade();
        SynchronizeFilmstripAdjustmentAvoidance();
        const bool footerActive = UpdateAdjustmentFooterVisuals();
        const bool filmstripActive = filmstripAdjustmentAvoidanceAnimating_;
        InvalidateRect(window_, nullptr, FALSE);
        if (heldActive || imageActive || videoActive || footerActive || filmstripActive) SetTimer(window_, kVideoAdjustmentsFadeTimer, 16, nullptr);
        else KillTimer(window_, kVideoAdjustmentsFadeTimer);
    }
    void QueueVideoAdjustmentPersistence() {
        ++videoAdjustmentEditGeneration_;
        videoAdjustmentEditedInSession_ = true;
        videoAdjustmentPersistenceSuppressedUntilEdit_ = false;
        if (!adjustmentPersistenceEnabled_) {
            videoAdjustmentDirtyWhilePersistenceDisabled_ = true;
            return;
        }
        if (videoAdjustmentHashResolved_) SetTimer(window_, kVideoAdjustmentPersistenceTimer, 300, nullptr);
        else pendingVideoAdjustmentSaves_[videoAdjustmentMediaGeneration_] = videoAdjustments_;
    }
    void FlushVideoAdjustmentPersistence() {
        KillTimer(window_, kVideoAdjustmentPersistenceTimer);
        if (!adjustmentPersistenceEnabled_ || videoAdjustmentPersistenceSuppressedUntilEdit_) return;
        if (videoAdjustmentHashResolved_) adjustmentPersistence_.Save(videoAdjustmentHash_, videoAdjustments_, AdjustmentMediaKind::Video);
    }
    void ResetVideoAdjustments() { videoAdjustments_ = {}; videoAdjustmentSource_ = AdjustmentSource::None; ApplyVideoAdjustments(); QueueVideoAdjustmentPersistence(); }
    void AutoVideoAdjustments() {
        AiImageBuffer image{};
        if (!videoPlayer_.CopyCurrentFrameBgra(image.pixels, image.width, image.height) || !image.width || !image.height) return;
        image.stride = image.width * 4;
        // Video is opaque; its transfer surface is displayed with alpha ignored, while the shared analyzer
        // treats zero alpha as transparent and skips those pixels.
        for (size_t offset = 3; offset < image.pixels.size(); offset += 4) image.pixels[offset] = 255;
        ImageAdjustments result = videoAdjustments_;
        if (!ComputeAutoImageAdjustments(image, result)) return;
        videoAdjustments_.exposure = result.exposure; videoAdjustments_.brightness = result.brightness; videoAdjustments_.contrast = result.contrast;
        videoAdjustments_.shadows = result.shadows; videoAdjustments_.highlights = result.highlights; videoAdjustments_.saturation = result.saturation;
        videoAdjustmentSource_ = AdjustmentSource::Auto;
        ApplyVideoAdjustments(); QueueVideoAdjustmentPersistence();
    }
    void UpdateVideoAdjustmentSlider(int index, POINT point) {
        if (index < 0 || index >= 7) return;
        videoAdjustmentSource_ = AdjustmentSource::None;
        const RECT slider = GetVideoAdjustmentsPanelPresentedLayout().sliders[index];
        const float normalized = std::clamp(static_cast<float>(point.x - slider.left) / static_cast<float>(std::max(1L, slider.right - slider.left)), 0.0f, 1.0f);
        const int minimum = index == 6 ? 0 : -100;
        const int maximum = 100;
        const float continuous = minimum + normalized * static_cast<float>(maximum - minimum);
        int value = std::clamp(static_cast<int>(std::lround(continuous)), minimum, maximum);
        const int nearestDetent = std::clamp(static_cast<int>(std::lround(continuous / 5.0f)) * 5, minimum, maximum);
        const bool zeroDetent = nearestDetent == 0;
        const float attraction = zeroDetent ? 1.75f : 0.30f;
        const float hold = zeroDetent ? 3.25f : 1.10f;
        if (videoAdjustmentDetentIndex_ == index && std::abs(continuous - videoAdjustmentDetentValue_) <= hold) {
            value = videoAdjustmentDetentValue_;
        } else if (std::abs(continuous - nearestDetent) <= attraction) {
            value = nearestDetent;
            videoAdjustmentDetentIndex_ = index;
            videoAdjustmentDetentValue_ = nearestDetent;
        } else {
            videoAdjustmentDetentIndex_ = -1;
        }
        SetAdjustmentSliderIntegerValue(videoAdjustments_, index, value);
        ApplyVideoAdjustments();
        QueueVideoAdjustmentPersistence();
    }
    int AdjustmentSliderIntegerValue(const ImageAdjustments& adjustments, int index) const {
        if (index == 0) return std::clamp(static_cast<int>(std::lround(adjustments.exposure * 50.0f)), -100, 100);
        if (index == 1) return std::clamp(static_cast<int>(std::lround(adjustments.brightness * 100.0f)), -100, 100);
        if (index == 2) return std::clamp(static_cast<int>(std::lround(adjustments.contrast * 100.0f)), -100, 100);
        if (index == 3) return std::clamp(static_cast<int>(std::lround(adjustments.shadows * 100.0f)), -100, 100);
        if (index == 4) return std::clamp(static_cast<int>(std::lround(adjustments.highlights * 100.0f)), -100, 100);
        if (index == 5) return std::clamp(static_cast<int>(std::lround(adjustments.saturation * 100.0f)), -100, 100);
        return std::clamp(static_cast<int>(std::lround(adjustments.sharpness / kSharpnessSliderMaximum * 100.0f)), 0, 100);
    }
    void SetAdjustmentSliderIntegerValue(ImageAdjustments& adjustments, int index, int value) {
        const float normalizedValue = static_cast<float>(std::clamp(value, index == 6 ? 0 : -100, 100)) / 100.0f;
        if (index == 0) adjustments.exposure = normalizedValue * 2.0f;
        else if (index == 1) adjustments.brightness = normalizedValue;
        else if (index == 2) adjustments.contrast = normalizedValue;
        else if (index == 3) adjustments.shadows = normalizedValue;
        else if (index == 4) adjustments.highlights = normalizedValue;
        else if (index == 5) adjustments.saturation = normalizedValue;
        else adjustments.sharpness = normalizedValue * kSharpnessSliderMaximum;
    }
    void LoadUserAdjustmentPreset() {
        DWORD saved = 0;
        if (!ReadSetting(L"UserAdjustmentPresetSaved", saved) || saved == 0) return;
        constexpr std::array<const wchar_t*, 7> names{
            L"UserAdjustmentPresetExposure", L"UserAdjustmentPresetBrightness", L"UserAdjustmentPresetContrast",
            L"UserAdjustmentPresetShadows", L"UserAdjustmentPresetHighlights", L"UserAdjustmentPresetSaturation",
            L"UserAdjustmentPresetSharpness" };
        ImageAdjustments preset{};
        for (int index = 0; index < static_cast<int>(names.size()); ++index) {
            DWORD stored = 0;
            if (!ReadSetting(names[index], stored) || stored > static_cast<DWORD>(index == 6 ? 100 : 200)) return;
            SetAdjustmentSliderIntegerValue(preset, index, index == 6 ? static_cast<int>(stored) : static_cast<int>(stored) - 100);
        }
        userAdjustmentPreset_ = preset;
        userAdjustmentPresetSaved_ = true;
    }
    void SaveUserAdjustmentPreset(const ImageAdjustments& adjustments) {
        constexpr std::array<const wchar_t*, 7> names{
            L"UserAdjustmentPresetExposure", L"UserAdjustmentPresetBrightness", L"UserAdjustmentPresetContrast",
            L"UserAdjustmentPresetShadows", L"UserAdjustmentPresetHighlights", L"UserAdjustmentPresetSaturation",
            L"UserAdjustmentPresetSharpness" };
        bool neutral = true;
        for (int index = 0; index < static_cast<int>(names.size()); ++index) {
            const int value = AdjustmentSliderIntegerValue(adjustments, index);
            neutral &= value == 0;
            WriteSetting(names[index], static_cast<DWORD>(index == 6 ? value : value + 100));
        }
        WriteSetting(L"UserAdjustmentPresetSaved", neutral ? 0 : 1);
        if (neutral) {
            for (const wchar_t* name : names) ApplicationSettings::DeleteDword(name);
            userAdjustmentPreset_ = {};
            userAdjustmentPresetSaved_ = false;
            if (imageAdjustmentSource_ == AdjustmentSource::User) imageAdjustmentSource_ = AdjustmentSource::None;
            if (videoAdjustmentSource_ == AdjustmentSource::User) videoAdjustmentSource_ = AdjustmentSource::None;
        } else {
            userAdjustmentPreset_ = adjustments;
            userAdjustmentPresetSaved_ = true;
        }
        adjustmentFooterSaveConfirmedAt_ = GetTickCount64();
        SetTimer(window_, kVideoAdjustmentsFadeTimer, 16, nullptr);
        InvalidateRect(window_, nullptr, FALSE);
    }
    void ApplyUserAdjustmentPresetToImage() {
        if (!userAdjustmentPresetSaved_) return;
        imageAdjustments_ = userAdjustmentPreset_;
        imageAdjustmentSource_ = AdjustmentSource::User;
        ApplyImageAdjustments();
        QueueImageAdjustmentPersistence();
    }
    void ApplyUserAdjustmentPresetToVideo() {
        if (!userAdjustmentPresetSaved_) return;
        videoAdjustments_ = userAdjustmentPreset_;
        videoAdjustmentSource_ = AdjustmentSource::User;
        ApplyVideoAdjustments();
        QueueVideoAdjustmentPersistence();
    }
    int AdjustmentSliderAt(const VideoAdjustmentsPanelLayout& panel, POINT point) const {
        const LONG verticalPadding = MulDiv(6, GetDpiForWindow(window_), 96);
        for (int index = 0; index < static_cast<int>(panel.sliders.size()); ++index) {
            const RECT hit{ panel.sliders[index].left, panel.sliders[index].top - verticalPadding,
                panel.sliders[index].right, panel.sliders[index].bottom + verticalPadding };
            if (PtInRect(&hit, point)) return index;
        }
        return -1;
    }
    bool CircularSliderThumbContains(POINT point, float centerX, float centerY) const {
        const float halfExtent = static_cast<float>(MulDiv(12, GetDpiForWindow(window_), 96));
        return point.x >= centerX - halfExtent && point.x <= centerX + halfExtent &&
            point.y >= centerY - halfExtent && point.y <= centerY + halfExtent;
    }
    int AdjustmentSliderThumbAt(const VideoAdjustmentsPanelLayout& panel, const ImageAdjustments& adjustments, POINT point) const {
        for (int index = 0; index < static_cast<int>(panel.sliders.size()); ++index) {
            const int value = AdjustmentSliderIntegerValue(adjustments, index);
            const float normalized = index == 6 ? static_cast<float>(value) / 100.0f : static_cast<float>(value + 100) / 200.0f;
            const RECT slider = panel.sliders[index];
            const float centerX = slider.left + (slider.right - slider.left) * normalized;
            const float centerY = (slider.top + slider.bottom) * 0.5f;
            if (CircularSliderThumbContains(point, centerX, centerY)) return index;
        }
        return -1;
    }
    int ConsumeAdjustmentWheelSteps(int index, int rawWheelDelta, int& hoveredIndex, int& remainder) {
        if (hoveredIndex != index) { hoveredIndex = index; remainder = 0; }
        remainder += rawWheelDelta;
        const int steps = remainder / WHEEL_DELTA;
        remainder %= WHEEL_DELTA;
        return steps;
    }
    ZoomHudLayout GetZoomHudLayout(const RECT& canvas, bool includeAdjustmentButton, bool forceZoomPercentage = false,
        std::optional<ZoomHudPosition> positionOverride = std::nullopt) const {
        const float scale = static_cast<float>(GetDpiForWindow(window_)) / 96.0f;
        const int zoomWidth = (showZoomPercentage_ || forceZoomPercentage) ? static_cast<int>(std::lround(72.0f * scale)) : 0;
        const int height = static_cast<int>(std::lround(30.0f * scale));
        const int buttonWidth = height;
        const int gap = static_cast<int>(std::lround(2.0f * scale));
        const int margin = static_cast<int>(std::lround(14.0f * scale));
        const ZoomHudPosition position = positionOverride.value_or(zoomHudPosition_);
        const bool left = position == ZoomHudPosition::BottomLeft || position == ZoomHudPosition::TopLeft;
        const bool top = position == ZoomHudPosition::TopLeft || position == ZoomHudPosition::TopRight;
        const int totalWidth = (includeAdjustmentButton ? buttonWidth : 0) + (zoomWidth ? (includeAdjustmentButton ? gap : 0) + zoomWidth : 0);
        const LONG defaultX = left ? canvas.left + margin : canvas.right - margin - totalWidth;
        const LONG defaultY = top ? canvas.top + margin : canvas.bottom - margin - height;
        const LONG x = defaultX;
        const LONG y = defaultY;
        const RECT combined{ x, y, x + totalWidth, y + height };
        const RECT zoom = includeAdjustmentButton ? (left ? RECT{ x, y, x + zoomWidth, y + height } : RECT{ combined.right - zoomWidth, y, combined.right, y + height }) : RECT{ x, y, x + zoomWidth, y + height };
        const RECT adjustments = includeAdjustmentButton ? (left ? RECT{ zoom.right + (zoomWidth ? gap : 0), y, combined.right, y + height } : RECT{ x, y, x + buttonWidth, y + height }) : RECT{};
        return { combined, zoom, adjustments, zoomWidth != 0 };
    }
    ZoomHudLayout GetImageZoomHudLayout(bool tutorialPreview = false) const {
        const D2D1_RECT_F bounds = ImageCanvasBounds();
        return GetZoomHudLayout({ static_cast<LONG>(bounds.left), static_cast<LONG>(bounds.top), static_cast<LONG>(bounds.right), static_cast<LONG>(bounds.bottom) },
            true, tutorialPreview, tutorialPreview ? std::optional(ZoomHudPosition::BottomRight) : std::nullopt);
    }
    ZoomHudLayout GetVideoZoomHudLayout() const { return GetZoomHudLayout(ModelCanvasBounds(), true); }
    ImageAdjustmentsPanelLayout GetImageAdjustmentsPanelTargetLayout(bool tutorialPreview = false) const {
        const ZoomHudLayout hud = GetImageZoomHudLayout(tutorialPreview);
        const D2D1_RECT_F canvas = ImageCanvasBounds();
        const UINT dpi = GetDpiForWindow(window_);
        const int gap = MulDiv(8, dpi, 96);
        const int width = std::min(MulDiv(370, dpi, 96), std::max(MulDiv(220, dpi, 96), static_cast<int>(canvas.right - canvas.left) - MulDiv(24, dpi, 96)));
        const int panelLeft = std::clamp(static_cast<int>(hud.combined.right) - width, static_cast<int>(canvas.left) + gap, std::max(static_cast<int>(canvas.left) + gap, static_cast<int>(canvas.right) - gap - width));
        const int bottom = static_cast<int>(hud.combined.top) - gap;
        const int height = std::min(MulDiv(238, dpi, 96), std::max(1, bottom - (static_cast<int>(canvas.top) + gap)));
        return MakeVideoAdjustmentsPanelLayout({ panelLeft, bottom - height, panelLeft + width, bottom }, false);
    }
    AdjustmentPanelLipLayout GetAdjustmentPanelLipLayout(const VideoAdjustmentsPanelLayout& panel, bool tutorialPreview = false) const {
        if (drawingHeldAdjustmentPanel_) return adjustmentPanelNavigation_.lip;
        // The lipped silhouette is intended for the bottom-right HUD anchor. Other HUD
        // positions retain the established rounded rectangle rather than forcing a foot
        // through a constrained or unrelated lower-overlay layout.
        const bool hudAtBottomRight = tutorialPreview || zoomHudPosition_ == ZoomHudPosition::BottomRight;
        if (!hudAtBottomRight) return {};

        const UINT dpi = GetDpiForWindow(window_);
        const LONG radius = MulDiv(10, dpi, 96);
        const LONG clearance = MulDiv(8, dpi, 96);
        const LONG minimumFootWidth = MulDiv(220, dpi, 96);
        // Video translates the finished image panel, including its footer, as one unit.
        const auto normal = VideoActive() || tutorialPreview ? GetImageAdjustmentsPanelTargetLayout(tutorialPreview) : panel;
        const ZoomHudLayout hud = GetImageZoomHudLayout(tutorialPreview);
        const LONG footLeft = normal.panel.left;
        const LONG footRight = std::min(normal.panel.right - radius * 2, hud.combined.left - clearance);
        if (footRight - footLeft < minimumFootWidth) return {};

        LONG footBottom = normal.panel.bottom;
        if (VideoActive() || tutorialPreview) {
            // Match the image filmstrip's 16-DIP canvas-bottom anchor. Videos have no
            // source_, so FilmstripEligible()/GetFilmstripBounds() cannot supply it.
            footBottom = static_cast<LONG>(ImageCanvasBounds().bottom) - MulDiv(16, dpi, 96);
        } else if (FilmstripEligible() && !filmstripAdjustmentSuppressed_) {
            footBottom = GetFilmstripBounds().bottom;
        } else {
            return {};
        }

        if (footBottom - normal.panel.bottom < MulDiv(34, dpi, 96)) return {};
        RECT foot{ footLeft, normal.panel.bottom, footRight, footBottom };
        OffsetRect(&foot, panel.panel.left - normal.panel.left, panel.panel.top - normal.panel.top);
        return { foot, true };
    }
    AdjustmentPanelActionLayout GetAdjustmentPanelActionLayout(const VideoAdjustmentsPanelLayout& panel,
        const AdjustmentPanelLipLayout& lip) const {
        if (!lip.active) return { panel.autoButton, panel.userButton, panel.saveButton, panel.originalButton, panel.resetButton };
        const UINT dpi = GetDpiForWindow(window_);
        const LONG inset = MulDiv(4, dpi, 96);
        const LONG gap = MulDiv(5, dpi, 96);
        const LONG buttonHeight = MulDiv(30, dpi, 96);
        const std::array<LONG, 5> widths{ MulDiv(42, dpi, 96), MulDiv(38, dpi, 96), MulDiv(42, dpi, 96), buttonHeight, MulDiv(44, dpi, 96) };
        const LONG bottom = lip.bounds.bottom - inset;
        const LONG top = bottom - buttonHeight;
        LONG left = lip.bounds.left + inset;
        auto next = [&](LONG width) {
            const RECT result{ left, top, left + width, bottom };
            left = result.right + gap;
            return result;
        };
        const RECT autoButton = next(widths[0]);
        const RECT originalButton = next(widths[3]);
        const RECT userButton = next(widths[1]);
        const RECT saveButton = next(widths[2]);
        const RECT resetButton{ lip.bounds.right - inset - widths[4], top, lip.bounds.right - inset, bottom };
        return { autoButton, userButton, saveButton, originalButton, resetButton };
    }
    AdjustmentFooterButton AdjustmentFooterButtonAt(const AdjustmentPanelActionLayout& actions, POINT point) const {
        if (PtInRect(&actions.autoButton, point)) return AdjustmentFooterButton::Auto;
        if (PtInRect(&actions.originalButton, point)) return AdjustmentFooterButton::Original;
        if (PtInRect(&actions.userButton, point)) return AdjustmentFooterButton::User;
        if (PtInRect(&actions.saveButton, point)) return AdjustmentFooterButton::Save;
        if (PtInRect(&actions.resetButton, point)) return AdjustmentFooterButton::Reset;
        return AdjustmentFooterButton::None;
    }
    void SetAdjustmentFooterHover(POINT point) {
        if (adjustmentPanelNavigation_.pending) return;
        AdjustmentFooterButton hovered = AdjustmentFooterButton::None;
        if (VideoAdjustmentsPanelOpen()) {
            const auto& panel = GetVideoAdjustmentsPanelPresentedLayout();
            hovered = AdjustmentFooterButtonAt(GetAdjustmentPanelActionLayout(panel, GetAdjustmentPanelLipLayout(panel)), point);
        } else if (ImageAdjustmentsPanelOpen()) {
            const auto& panel = GetImageAdjustmentsPanelLayout();
            hovered = AdjustmentFooterButtonAt(GetAdjustmentPanelActionLayout(panel, GetAdjustmentPanelLipLayout(panel)), point);
        }
        if (hovered == adjustmentFooterHovered_) return;
        UpdateAdjustmentFooterVisuals();
        adjustmentFooterHoverStart_ = adjustmentFooterHoverProgress_;
        adjustmentFooterHovered_ = hovered;
        adjustmentFooterHoverStartedAt_ = GetTickCount64();
        adjustmentFooterHoverAnimating_ = true;
        SetTimer(window_, kVideoAdjustmentsFadeTimer, 16, nullptr);
    }
    bool UpdateAdjustmentFooterVisuals() {
        bool active = false;
        if (adjustmentFooterHoverAnimating_) {
            const float progress = std::clamp(static_cast<float>(GetTickCount64() - adjustmentFooterHoverStartedAt_) / static_cast<float>(kVideoPlaybackSpeedHoverDurationMs), 0.0f, 1.0f);
            adjustmentFooterHoverProgress_ = adjustmentFooterHoverStart_ + ((adjustmentFooterHovered_ == AdjustmentFooterButton::None ? 0.0f : 1.0f) - adjustmentFooterHoverStart_) * SmoothTransitionProgress(progress);
            adjustmentFooterHoverAnimating_ = progress < 1.0f;
            active |= adjustmentFooterHoverAnimating_;
        }
        if (adjustmentFooterSaveConfirmedAt_ != 0) {
            if (GetTickCount64() - adjustmentFooterSaveConfirmedAt_ < 260) active = true;
            else adjustmentFooterSaveConfirmedAt_ = 0;
        }
        return active;
    }
    RECT AdjustmentPanelRenderedRevealBounds(const VideoAdjustmentsPanelLayout& panel, float reveal,
        const AdjustmentPanelLipLayout& lip) const {
        if (!lip.active) return AdjustmentPanelRevealBounds(panel, reveal);
        RECT bounds = panel.panel;
        bounds.bottom = lip.bounds.bottom;
        const float progress = std::clamp(reveal, 0.0f, 1.0f);
        bounds.top = static_cast<LONG>(std::lround(bounds.bottom + (panel.panel.top - bounds.bottom) * progress));
        return bounds;
    }
    const ImageAdjustmentsPanelLayout& GetImageAdjustmentsPanelLayout() const {
        return ImageAdjustmentsPanelVisible() ? videoAdjustmentsPanelPresentedLayout_ : imageAdjustmentsPanelTargetLayout_;
    }
    void ApplyImageAdjustments() {
        imageAdjustedBitmap_.Reset();
        InvalidateRect(window_, nullptr, FALSE);
    }
    void QueueImageAdjustmentPersistence() {
        ++imageAdjustmentEditGeneration_;
        imageAdjustmentEditedInSession_ = true;
        imageAdjustmentPersistenceSuppressedUntilEdit_ = false;
        if (!adjustmentPersistenceEnabled_) {
            imageAdjustmentDirtyWhilePersistenceDisabled_ = true;
            return;
        }
        if (imageAdjustmentHashResolved_) SetTimer(window_, kImageAdjustmentPersistenceTimer, 300, nullptr);
        else pendingImageAdjustmentSaves_[imageAdjustmentMediaGeneration_] = imageAdjustments_;
    }
    void FlushImageAdjustmentPersistence() {
        KillTimer(window_, kImageAdjustmentPersistenceTimer);
        if (!adjustmentPersistenceEnabled_ || imageAdjustmentPersistenceSuppressedUntilEdit_) return;
        if (imageAdjustmentHashResolved_) adjustmentPersistence_.Save(imageAdjustmentHash_, imageAdjustments_);
    }
    void ResetImageAdjustments() { imageAdjustments_ = {}; imageAdjustmentSource_ = AdjustmentSource::None; ApplyImageAdjustments(); QueueImageAdjustmentPersistence(); }
    bool ImageAdjustmentsPanelOpen() const {
        return adjustmentPanelNavigation_.pending ? !VideoActive() && adjustmentPanelNavigation_.open : imageAdjustmentsPanelOpen_;
    }
    bool ImageAdjustmentsPanelContains(POINT point) const {
        if (adjustmentPanelNavigation_.pending || !imageAdjustmentsPanelOpen_) return false;
        const ImageAdjustmentsPanelLayout& layout = GetImageAdjustmentsPanelLayout();
        const RECT panel = AdjustmentPanelRenderedRevealBounds(layout, imageAdjustmentsPanelOpacity_, GetAdjustmentPanelLipLayout(layout));
        return PtInRect(&panel, point) != FALSE;
    }
    bool ImageAdjustmentsPanelVisible() const {
        return imageAdjustmentsPanelOpen_ || imageAdjustmentsPanelFadeActive_ || imageAdjustmentsPanelOpacity_ > 0.001f;
    }
    void SetImageAdjustmentsPanelOpen(bool open) {
        if (adjustmentPanelNavigation_.pending) { SetVideoAdjustmentsPanelOpen(open); return; }
        const bool wasMoving = VideoAdjustmentsPanelMotionActive();
        if (wasMoving) UpdateVideoAdjustmentsPanelPlacementMotion();
        imageAdjustmentsDragging_ = -1;
        imageAdjustmentThumbGrab_ = false;
        imageAdjustmentWheelRow_ = -1;
        imageAdjustmentWheelRemainder_ = 0;
        filmstripPreviewGeometryValid_ = false;
        if (!open && imageAdjustmentsOriginalPreviewActive_) {
            SetImageAdjustmentsOriginalPreview(false);
            if (GetCapture() == window_) ReleaseCapture();
        }
        SetAdjustmentPanelOpen(imageAdjustmentsPanelOpen_, imageAdjustmentsPanelFadeActive_,
            imageAdjustmentsPanelOpacity_, imageAdjustmentsPanelFadeStartOpacity_,
            imageAdjustmentsPanelFadeStartedAt_, open);
        imageAdjustmentsPanelTargetLayout_ = GetImageAdjustmentsPanelTargetLayout();
        StopVideoAdjustmentsPanelMotion();
        videoAdjustmentsPanelPresentedLayout_ = imageAdjustmentsPanelTargetLayout_;
        SynchronizeFilmstripAdjustmentAvoidance();
        InvalidateRect(window_, nullptr, FALSE);
    }
    void ToggleAdjustments() {
        if (VideoActive()) { videoPlaybackSpeedPanelOpen_ = false; SetVideoAdjustmentsPanelOpen(!VideoAdjustmentsPanelOpen()); }
        else SetImageAdjustmentsPanelOpen(!ImageAdjustmentsPanelOpen());
    }
    void UpdateImageAdjustmentSlider(int index, POINT point) {
        if (index < 0 || index >= 7) return;
        imageAdjustmentSource_ = AdjustmentSource::None;
        const RECT slider = GetImageAdjustmentsPanelLayout().sliders[index];
        const float position = std::clamp(static_cast<float>(point.x - slider.left) / static_cast<float>(std::max(1L, slider.right - slider.left)), 0.0f, 1.0f);
        const int minimum = index == 6 ? 0 : -100;
        const float continuous = minimum + position * static_cast<float>(100 - minimum);
        int integer = std::clamp(static_cast<int>(std::lround(continuous)), minimum, 100);
        const int detent = std::clamp(static_cast<int>(std::lround(continuous / 5.0f)) * 5, minimum, 100);
        const bool zeroDetent = detent == 0;
        if (imageAdjustmentDetentIndex_ == index && std::abs(continuous - imageAdjustmentDetentValue_) <= (zeroDetent ? 3.25f : 1.10f)) integer = imageAdjustmentDetentValue_;
        else if (std::abs(continuous - detent) <= (zeroDetent ? 1.75f : 0.30f)) { integer = detent; imageAdjustmentDetentIndex_ = index; imageAdjustmentDetentValue_ = detent; }
        else imageAdjustmentDetentIndex_ = -1;
        SetAdjustmentSliderIntegerValue(imageAdjustments_, index, integer);
        ApplyImageAdjustments();
        QueueImageAdjustmentPersistence();
    }
    bool HandleAdjustmentPanelWheel(POINT point, int rawWheelDelta) {
        if (adjustmentPanelNavigation_.pending) return HeldAdjustmentPanelContains(point);
        if (ImageAdjustmentsPanelContains(point)) {
            const int index = AdjustmentSliderAt(GetImageAdjustmentsPanelLayout(), point);
            if (index < 0) { imageAdjustmentWheelRow_ = -1; imageAdjustmentWheelRemainder_ = 0; return true; }
            const int steps = ConsumeAdjustmentWheelSteps(index, rawWheelDelta, imageAdjustmentWheelRow_, imageAdjustmentWheelRemainder_);
            if (!steps) return true;
            const int value = AdjustmentSliderIntegerValue(imageAdjustments_, index);
            const int adjusted = std::clamp(value - steps, index == 6 ? 0 : -100, 100);
            if (adjusted == value) return true;
            imageAdjustmentSource_ = AdjustmentSource::None;
            SetAdjustmentSliderIntegerValue(imageAdjustments_, index, adjusted);
            ApplyImageAdjustments();
            QueueImageAdjustmentPersistence();
            return true;
        }
        if (VideoAdjustmentsPanelContains(point)) {
            const int index = AdjustmentSliderAt(GetVideoAdjustmentsPanelPresentedLayout(), point);
            if (index < 0) { videoAdjustmentWheelRow_ = -1; videoAdjustmentWheelRemainder_ = 0; return true; }
            const int steps = ConsumeAdjustmentWheelSteps(index, rawWheelDelta, videoAdjustmentWheelRow_, videoAdjustmentWheelRemainder_);
            if (!steps) return true;
            const int value = AdjustmentSliderIntegerValue(videoAdjustments_, index);
            const int adjusted = std::clamp(value - steps, index == 6 ? 0 : -100, 100);
            if (adjusted == value) return true;
            videoAdjustmentSource_ = AdjustmentSource::None;
            SetAdjustmentSliderIntegerValue(videoAdjustments_, index, adjusted);
            ApplyVideoAdjustments();
            QueueVideoAdjustmentPersistence();
            return true;
        }
        imageAdjustmentWheelRow_ = -1;
        imageAdjustmentWheelRemainder_ = 0;
        videoAdjustmentWheelRow_ = -1;
        videoAdjustmentWheelRemainder_ = 0;
        return false;
    }
    bool BuildAiImage(AiImageBuffer& image) {
        if (!source_ || !wicFactory_) return false;
        UINT sourceWidth = 0, sourceHeight = 0;
        if (FAILED(source_->GetSize(&sourceWidth, &sourceHeight)) || !sourceWidth || !sourceHeight) return false;
        constexpr UINT maxEdge = 640;
        const float scale = std::min(1.0f, static_cast<float>(maxEdge) / std::max(sourceWidth, sourceHeight));
        image.width = std::max(1u, static_cast<UINT>(std::lround(sourceWidth * scale)));
        image.height = std::max(1u, static_cast<UINT>(std::lround(sourceHeight * scale)));
        image.stride = image.width * 4; image.pixels.resize(static_cast<size_t>(image.stride) * image.height);
        ComPtr<IWICBitmapScaler> scaler;
        return SUCCEEDED(wicFactory_->CreateBitmapScaler(&scaler)) &&
            SUCCEEDED(scaler->Initialize(source_.Get(), image.width, image.height, WICBitmapInterpolationModeFant)) &&
            SUCCEEDED(scaler->CopyPixels(nullptr, image.stride, static_cast<UINT>(image.pixels.size()), image.pixels.data()));
    }

    void StartAiAnalysis() {
        if (aiAnalysisRunning_.exchange(true)) return;
        AiImageBuffer image;
        if (!BuildAiImage(image)) { aiAnalysisRunning_ = false; return; }
        if (aiAnalysisThread_.joinable()) aiAnalysisThread_.join();
        const uint64_t generation = ++aiRequestGeneration_;
        const std::wstring path = currentPath_; const ContentKind kind = contentKind_;
        aiAnalysisThread_ = std::thread([this, generation, path, kind, image = std::move(image)]() mutable {
            auto* result = new AiAnalysisResult{}; result->generation = generation; result->path = path; result->contentKind = kind; result->workerId = std::this_thread::get_id();
            result->succeeded = ComputeAutoImageAdjustments(image, result->adjustments);
            if (!PostMessageW(window_, kAiAnalysisCompleteMessage, 0, reinterpret_cast<LPARAM>(result))) { delete result; aiAnalysisRunning_ = false; }
        });
    }

    void AiAnalysisCompleteMessage(AiAnalysisResult* result) {
        std::unique_ptr<AiAnalysisResult> owned(result);
        if (!result) return;
        if (aiAnalysisThread_.joinable() && aiAnalysisThread_.get_id() == result->workerId) aiAnalysisThread_.join();
        aiAnalysisRunning_ = false;
        if (!result->succeeded || result->generation != aiRequestGeneration_ || result->contentKind != ContentKind::Image2D || contentKind_ != ContentKind::Image2D || !PathsEqual(fs::path(result->path), fs::path(currentPath_))) return;
        imageAdjustments_.exposure = result->adjustments.exposure;
        imageAdjustments_.brightness = result->adjustments.brightness;
        imageAdjustments_.contrast = result->adjustments.contrast;
        imageAdjustments_.shadows = result->adjustments.shadows;
        imageAdjustments_.highlights = result->adjustments.highlights;
        imageAdjustments_.saturation = result->adjustments.saturation;
        imageAdjustmentSource_ = AdjustmentSource::Auto;
        ApplyImageAdjustments();
        QueueImageAdjustmentPersistence();
    }
    bool BeginImageAdjustmentsInteraction(POINT point) {
        if (adjustmentPanelNavigation_.pending) return HeldAdjustmentPanelContains(point);
        if (!source_) return false;
        if (imageAdjustmentsPanelOpen_) {
            const ImageAdjustmentsPanelLayout panel = GetImageAdjustmentsPanelLayout();
            if (ImageAdjustmentsPanelContains(point)) {
                const AdjustmentPanelActionLayout actions = GetAdjustmentPanelActionLayout(panel, GetAdjustmentPanelLipLayout(panel));
                adjustmentFooterPressed_ = AdjustmentFooterButtonAt(actions, point);
                const int thumb = AdjustmentSliderThumbAt(panel, imageAdjustments_, point);
                const int slider = thumb >= 0 ? thumb : AdjustmentSliderAt(panel, point);
                if (slider >= 0) { imageAdjustmentsDragging_ = slider; imageAdjustmentThumbGrab_ = thumb >= 0; imageAdjustmentDetentIndex_ = -1; if (!imageAdjustmentThumbGrab_) UpdateImageAdjustmentSlider(slider, point); return true; }
                if (PtInRect(&actions.autoButton, point)) { StartAiAnalysis(); return true; }
                if (PtInRect(&actions.userButton, point)) { ApplyUserAdjustmentPresetToImage(); return true; }
                if (PtInRect(&actions.saveButton, point)) { SaveUserAdjustmentPreset(imageAdjustments_); return true; }
                if (PtInRect(&actions.originalButton, point)) { SetImageAdjustmentsOriginalPreview(true); return true; }
                if (PtInRect(&actions.resetButton, point)) { ResetImageAdjustments(); return true; }
                return true;
            }
        }
        return false;
    }
    bool ContinueImageAdjustmentsInteraction(POINT point) {
        if (imageAdjustmentsDragging_ < 0) return false;
        UpdateImageAdjustmentSlider(imageAdjustmentsDragging_, point);
        return true;
    }
    bool EndImageAdjustmentsInteraction(POINT point) {
        const bool footerPressed = adjustmentFooterPressed_ != AdjustmentFooterButton::None;
        adjustmentFooterPressed_ = AdjustmentFooterButton::None;
        if (imageAdjustmentsOriginalPreviewActive_) { SetImageAdjustmentsOriginalPreview(false); return true; }
        if (footerPressed) { InvalidateRect(window_, nullptr, FALSE); return true; }
        if (imageAdjustmentsDragging_ < 0) return false;
        if (!imageAdjustmentThumbGrab_) UpdateImageAdjustmentSlider(imageAdjustmentsDragging_, point);
        imageAdjustmentsDragging_ = -1;
        imageAdjustmentThumbGrab_ = false;
        imageAdjustmentDetentIndex_ = -1;
        FlushImageAdjustmentPersistence();
        return true;
    }
    void CancelImageAdjustmentsInteraction() {
        imageAdjustmentsDragging_ = -1;
        imageAdjustmentThumbGrab_ = false;
        SetImageAdjustmentsOriginalPreview(false);
    }
    bool VideoControlsInteractive() const { return VideoActive() && videoControlsOpacity_ > 0.05f; }
    ButtonKind VideoControlAt(POINT point) const {
        if (!VideoControlsInteractive()) return ButtonKind::None;
        const VideoControlsLayout layout = GetVideoControlsLayout();
        if (PtInRect(&layout.playPause, point)) return ButtonKind::VideoPlayPause;
        if (PtInRect(&layout.stepBackward, point)) return ButtonKind::VideoStepBackward;
        if (PtInRect(&layout.stepForward, point)) return ButtonKind::VideoStepForward;
        if (PtInRect(&layout.mute, point)) return ButtonKind::VideoMute;
        if (PtInRect(&layout.autoPlayNext, point)) return ButtonKind::VideoAutoPlayNext;
        if (PtInRect(&layout.playbackSpeed, point)) return ButtonKind::VideoPlaybackSpeed;
        if (PtInRect(&layout.fullscreen, point)) return ButtonKind::VideoFullscreen;
        return ButtonKind::None;
    }
    bool VideoScrubberContains(POINT point) const {
        if (!VideoControlsInteractive()) return false;
        const VideoControlsLayout layout = GetVideoControlsLayout();
        const RECT hit{ layout.scrubber.left, layout.scrubber.top + (layout.scrubber.bottom - layout.scrubber.top) / 2 - MulDiv(12, GetDpiForWindow(window_), 96),
            layout.scrubber.right, layout.scrubber.top + (layout.scrubber.bottom - layout.scrubber.top) / 2 + MulDiv(12, GetDpiForWindow(window_), 96) };
        return (hit.right > hit.left && PtInRect(&hit, point)) || VideoScrubberThumbContains(point);
    }
    bool VideoScrubberThumbContains(POINT point) const {
        if (!VideoControlsInteractive()) return false;
        double current = 0.0, duration = 0.0;
        if (!videoPlayer_.GetPlaybackTimes(current, duration)) return false;
        const RECT scrubber = GetVideoControlsLayout().scrubber;
        const float progress = duration > 0.0 ? std::clamp(static_cast<float>(current / duration), 0.0f, 1.0f) : 0.0f;
        return CircularSliderThumbContains(point, scrubber.left + (scrubber.right - scrubber.left) * progress,
            (scrubber.top + scrubber.bottom) * 0.5f);
    }
    bool VideoVolumeContains(POINT point) const {
        if (!VideoControlsInteractive()) return false;
        const RECT volume = GetVideoControlsLayout().volume;
        const int padding = MulDiv(6, GetDpiForWindow(window_), 96);
        const RECT hit{ volume.left, volume.top - padding, volume.right, volume.bottom + padding };
        return (hit.right > hit.left && PtInRect(&hit, point)) || VideoVolumeThumbContains(point);
    }
    bool VideoVolumeThumbContains(POINT point) const {
        if (!VideoControlsInteractive()) return false;
        const RECT volume = GetVideoControlsLayout().volume;
        return CircularSliderThumbContains(point, volume.left + (volume.right - volume.left) * static_cast<float>(videoVolume_),
            (volume.top + volume.bottom) * 0.5f);
    }
    bool VideoCanvasContains(POINT point) const {
        if (!VideoActive()) return false;
        const RECT canvas = ModelCanvasBounds();
        return PtInRect(&canvas, point) != FALSE;
    }
    bool VideoControlsRevealZoneContains(POINT point) const {
        if (!VideoActive()) return false;
        const RECT canvas = ModelCanvasBounds();
        const VideoControlsLayout controls = GetVideoControlsLayout();
        const LONG margin = MulDiv(16, GetDpiForWindow(window_), 96);
        const RECT zone{ canvas.left, std::max(canvas.top, controls.island.top - margin), canvas.right, canvas.bottom };
        return PtInRect(&zone, point) != FALSE;
    }
    bool VideoControlsContains(POINT point) const {
        if (!VideoControlsInteractive()) return false;
        const RECT island = GetVideoControlsLayout().island;
        return VideoAdjustmentsPanelContains(point) || VideoPlaybackSpeedPanelContains(point) || PtInRect(&island, point);
    }
    bool VideoCursorMayHide() const { return !HasOverlay() && !TutorialActive() && !videoAdjustmentsPanelOpen_ && !videoPlaybackSpeedPanelOpen_; }
    void RestoreVideoCursor() {
        if (!videoCursorHidden_) return;
        ShowCursor(TRUE);
        videoCursorHidden_ = false;
    }
    void HideVideoCursorIfAppropriate() {
        if (videoCursorHidden_ || !VideoCursorMayHide() || !VideoActive() || !videoPlayer_.Playing() || videoControlsOpacity_ > 0.01f) return;
        POINT point{};
        if (!GetCursorPos(&point) || !ScreenToClient(window_, &point)) return;
        const RECT canvas = ModelCanvasBounds();
        if (!PtInRect(&canvas, point)) return;
        ShowCursor(FALSE);
        videoCursorHidden_ = true;
    }
    void ShowVideoControls(bool invalidate = true) {
        if (!VideoActive()) return;
        RestoreVideoCursor();
        const bool visibilityChanged = videoControlsOpacity_ < 0.999f || videoControlsFadeActive_;
        videoControlsOpacity_ = 1.0f;
        videoControlsFadeActive_ = false;
        videoControlsLastActivity_ = GetTickCount64();
        KillTimer(window_, kVideoControlsTimer);
        if (VideoUserPlaybackActive() && !videoControlsPointerOver_ && !videoScrubbing_ && !videoVolumeDragging_ && !videoPlaybackSpeedPanelOpen_)
            SetTimer(window_, kVideoControlsTimer, static_cast<UINT>(kVideoControlsIdleDelayMs), nullptr);
        if (visibilityChanged) SynchronizeVideoAdjustmentsPanelPresentedLayout(true);
        if (invalidate || visibilityChanged) InvalidateRect(window_, nullptr, FALSE);
    }
    void ResetVideoControls() {
        KillTimer(window_, kVideoControlsTimer);
        KillTimer(window_, kVideoPlaybackSpeedHoverTimer);
        if (!imageAdjustmentsPanelFadeActive_ && !(adjustmentPanelNavigation_.pending && adjustmentPanelNavigation_.fadeActive))
            KillTimer(window_, kVideoAdjustmentsFadeTimer);
        StopVideoAdjustmentsPanelMotion();
        StopVideoStepHold();
        SetVideoAdjustmentsOriginalPreview(false);
        videoControlsOpacity_ = 1.0f;
        videoControlsFadeActive_ = false;
        videoControlsPointerOver_ = false;
        videoScrubbing_ = false;
        videoScrubberThumbGrab_ = false;
        videoVolumeDragging_ = false;
        videoVolumeThumbGrab_ = false;
        videoWasPlayingBeforeScrub_ = false;
        videoAdjustmentsPanelOpen_ = false;
        videoAdjustmentsPanelFadeActive_ = false;
        videoAdjustmentsPanelOpacity_ = 0.0f;
        videoPlaybackSpeedPanelOpen_ = false;
        videoPlaybackSpeedHovered_ = -1;
        videoPlaybackSpeedHoverAnimating_ = false;
        videoPlaybackSpeedHoverProgress_.fill(0.0f);
        videoAdjustmentsDragging_ = -1;
        videoAdjustmentThumbGrab_ = false;
        videoControlsHovered_ = ButtonKind::None;
        videoControlsLastActivity_ = GetTickCount64();
        RestoreVideoCursor();
    }
    void StopVideoControls() {
        KillTimer(window_, kVideoControlsTimer);
        KillTimer(window_, kVideoFullscreenGlyphTimer);
        KillTimer(window_, kVideoPlaybackSpeedHoverTimer);
        if (!imageAdjustmentsPanelFadeActive_ && !(adjustmentPanelNavigation_.pending && adjustmentPanelNavigation_.fadeActive))
            KillTimer(window_, kVideoAdjustmentsFadeTimer);
        StopVideoAdjustmentsPanelMotion();
        StopVideoStepHold();
        SetVideoAdjustmentsOriginalPreview(false);
        videoScrubbing_ = false;
        videoScrubberThumbGrab_ = false;
        videoVolumeDragging_ = false;
        videoVolumeThumbGrab_ = false;
        videoWasPlayingBeforeScrub_ = false;
        videoAdjustmentsPanelOpen_ = false;
        videoAdjustmentsPanelFadeActive_ = false;
        videoAdjustmentsPanelOpacity_ = 0.0f;
        videoPlaybackSpeedPanelOpen_ = false;
        videoPlaybackSpeedHovered_ = -1;
        videoPlaybackSpeedHoverAnimating_ = false;
        videoPlaybackSpeedHoverProgress_.fill(0.0f);
        videoAdjustmentsDragging_ = -1;
        videoAdjustmentThumbGrab_ = false;
        videoControlsFadeActive_ = false;
        videoControlsOpacity_ = 0.0f;
        videoControlsHovered_ = ButtonKind::None;
        videoFullscreenGlyphHoverProgress_ = 0.0f;
        videoFullscreenGlyphHoverStart_ = 0.0f;
        videoFullscreenGlyphHoverTarget_ = 0.0f;
        RestoreVideoCursor();
    }
    void UpdateVideoScrub(POINT point) {
        CancelVideoAutoPlayNextCountdown();
        double current = 0.0, duration = 0.0;
        if (!videoPlayer_.GetPlaybackTimes(current, duration)) return;
        const RECT scrubber = GetVideoControlsLayout().scrubber;
        if (scrubber.right <= scrubber.left) return;
        const float fraction = std::clamp(static_cast<float>(point.x - scrubber.left) / static_cast<float>(scrubber.right - scrubber.left), 0.0f, 1.0f);
        videoScrubSeconds_ = duration * fraction;
        const bool seekStarted = videoPlayer_.Seek(videoScrubSeconds_);
        if (seekStarted && !videoPlayer_.Playing()) videoPausedSeekRefreshPending_ = true;
        InvalidateRect(window_, nullptr, FALSE);
    }
    bool BeginVideoControlsInteraction(POINT point) {
        if (HeldAdjustmentPanelContains(point)) return true;
        if (!VideoActive()) return false;
        if (lowerUiMorph_.active && !VideoAdjustmentsPanelContains(point) && !VideoPlaybackSpeedPanelContains(point) &&
            (LowerUiMorphContains(point) || VideoControlsContains(point))) return true;
        if (!VideoControlsContains(point) && !VideoControlsRevealZoneContains(point) &&
            !VideoAdjustmentsPanelContains(point) && !VideoPlaybackSpeedPanelContains(point)) return false;
        ShowVideoControls();
        if (videoPlaybackSpeedPanelOpen_) {
            const VideoPlaybackSpeedPanelLayout panel = GetVideoPlaybackSpeedPanelLayout();
            if (PtInRect(&panel.panel, point)) {
                for (size_t index = 0; index < panel.rates.size(); ++index) {
                    if (PtInRect(&panel.rates[index], point)) {
                        const DWORD percent = kVideoPlaybackRatePercents[index];
                        if (videoPlayer_.PlaybackRateSupported(PlaybackRateFromPercent(percent))) {
                            SelectVideoPlaybackRate(percent);
                            SetVideoPlaybackSpeedPanelOpen(false);
                        }
                        return true;
                    }
                }
                return true;
            }
            if (!VideoControlsContains(point)) { SetVideoPlaybackSpeedPanelOpen(false); return true; }
        }
        if (videoAdjustmentsPanelOpen_) {
            const VideoAdjustmentsPanelLayout& panel = GetVideoAdjustmentsPanelPresentedLayout();
            if (VideoAdjustmentsPanelContains(point)) {
                const AdjustmentPanelActionLayout actions = GetAdjustmentPanelActionLayout(panel, GetAdjustmentPanelLipLayout(panel));
                adjustmentFooterPressed_ = AdjustmentFooterButtonAt(actions, point);
                const int thumb = AdjustmentSliderThumbAt(panel, videoAdjustments_, point);
                const int slider = thumb >= 0 ? thumb : AdjustmentSliderAt(panel, point);
                if (slider >= 0) { videoAdjustmentsDragging_ = slider; videoAdjustmentThumbGrab_ = thumb >= 0; videoAdjustmentDetentIndex_ = -1; if (!videoAdjustmentThumbGrab_) UpdateVideoAdjustmentSlider(slider, point); return true; }
                if (PtInRect(&actions.autoButton, point)) { AutoVideoAdjustments(); return true; }
                if (PtInRect(&actions.userButton, point)) { ApplyUserAdjustmentPresetToVideo(); return true; }
                if (PtInRect(&actions.saveButton, point)) { SaveUserAdjustmentPreset(videoAdjustments_); return true; }
                if (PtInRect(&actions.originalButton, point)) { SetVideoAdjustmentsOriginalPreview(true); return true; }
                if (PtInRect(&actions.resetButton, point)) { ResetVideoAdjustments(); return true; }
                return true;
            }
        }
        if (!VideoControlsContains(point)) return false;
        videoControlsPointerOver_ = true;
        KillTimer(window_, kVideoControlsTimer);
        if (VideoScrubberContains(point)) {
            StopVideoStepHold();
            videoWasPlayingBeforeScrub_ = videoPlayer_.Playing();
            if (videoWasPlayingBeforeScrub_) ToggleVideoPlayPause();
            videoScrubbing_ = true;
            videoScrubberThumbGrab_ = VideoScrubberThumbContains(point);
            if (!videoScrubberThumbGrab_) UpdateVideoScrub(point);
            return true;
        }
        if (VideoVolumeContains(point)) {
            videoVolumeDragging_ = true;
            videoVolumeThumbGrab_ = VideoVolumeThumbContains(point);
            if (!videoVolumeThumbGrab_) UpdateVideoVolume(point);
            return true;
        }
        const ButtonKind control = VideoControlAt(point);
        if (control == ButtonKind::VideoPlayPause) ToggleVideoPlayPause();
        else if (control == ButtonKind::VideoStepBackward) BeginVideoStepHold(-1);
        else if (control == ButtonKind::VideoStepForward) BeginVideoStepHold(1);
        else if (control == ButtonKind::VideoMute) { ToggleVideoMute(); ShowVideoControls(); }
        else if (control == ButtonKind::VideoAutoPlayNext) ToggleVideoAutoPlayNext();
        else if (control == ButtonKind::VideoPlaybackSpeed) SetVideoPlaybackSpeedPanelOpen(!videoPlaybackSpeedPanelOpen_);
        else if (control == ButtonKind::VideoFullscreen) { videoFullscreenToggleTick_ = GetTickCount64(); ToggleVideoFullscreen(); }
        return true;
    }
    bool ContinueVideoControlsInteraction(POINT point) {
        if (videoAdjustmentsDragging_ >= 0) { UpdateVideoAdjustmentSlider(videoAdjustmentsDragging_, point); return true; }
        if (videoVolumeDragging_) { UpdateVideoVolume(point); return true; }
        if (!videoScrubbing_) return false;
        ShowVideoControls();
        videoScrubbing_ = true;
        UpdateVideoScrub(point);
        return true;
    }
    bool EndVideoControlsInteraction(POINT point) {
        const bool footerPressed = adjustmentFooterPressed_ != AdjustmentFooterButton::None;
        adjustmentFooterPressed_ = AdjustmentFooterButton::None;
        if (videoAdjustmentsOriginalPreviewActive_) { SetVideoAdjustmentsOriginalPreview(false); return true; }
        if (footerPressed) { InvalidateRect(window_, nullptr, FALSE); return true; }
        if (videoAdjustmentsDragging_ >= 0) { if (!videoAdjustmentThumbGrab_) UpdateVideoAdjustmentSlider(videoAdjustmentsDragging_, point); videoAdjustmentsDragging_ = -1; videoAdjustmentThumbGrab_ = false; videoAdjustmentDetentIndex_ = -1; FlushVideoAdjustmentPersistence(); return true; }
        if (videoStepHoldDirection_) {
            StopVideoStepHold();
            ShowVideoControls();
            return true;
        }
        if (videoVolumeDragging_) { if (!videoVolumeThumbGrab_) UpdateVideoVolume(point); videoVolumeDragging_ = false; videoVolumeThumbGrab_ = false; return true; }
        if (!videoScrubbing_) return false;
        if (!videoScrubberThumbGrab_) UpdateVideoScrub(point);
        videoScrubbing_ = false;
        videoScrubberThumbGrab_ = false;
        const bool resumePlayback = videoWasPlayingBeforeScrub_;
        videoWasPlayingBeforeScrub_ = false;
        if (resumePlayback && VideoActive() && !videoPlayer_.Playing()) ToggleVideoPlayPause();
        else ShowVideoControls();
        return true;
    }
    void UpdateVideoControlsMouse(POINT point) {
        if (!VideoActive()) return;
        RestoreVideoCursor();
        const ButtonKind previousHovered = videoControlsHovered_;
        const bool volumeWasHot = VideoVolumeContains(lastMousePoint_);
        lastMousePoint_ = point;
        const bool wasPointerOver = videoControlsPointerOver_;
        const bool revealZone = VideoControlsRevealZoneContains(point);
        const bool activeInteraction = videoScrubbing_ || videoVolumeDragging_ || videoAdjustmentsDragging_ >= 0 || videoAdjustmentsOriginalPreviewActive_ || videoPlaybackSpeedPanelOpen_;
        if (!VideoUserPlaybackActive() || revealZone || activeInteraction) ShowVideoControls(false);
        videoControlsPointerOver_ = VideoControlsContains(point) || revealZone || activeInteraction;
        videoControlsHovered_ = VideoControlAt(point);
        SetVideoPlaybackSpeedHover(VideoPlaybackSpeedRateAt(point));
        SetVideoFullscreenGlyphHover(videoControlsHovered_ == ButtonKind::VideoFullscreen);
        if (videoControlsPointerOver_) KillTimer(window_, kVideoControlsTimer);
        else if (wasPointerOver && VideoUserPlaybackActive()) {
            videoControlsFadeActive_ = false;
            videoControlsLastActivity_ = GetTickCount64();
            SetTimer(window_, kVideoControlsTimer, static_cast<UINT>(kVideoControlsIdleDelayMs), nullptr);
        }
        if (videoAdjustmentsDragging_ >= 0) UpdateVideoAdjustmentSlider(videoAdjustmentsDragging_, point);
        if (videoVolumeDragging_) UpdateVideoVolume(point);
        if (videoScrubbing_) UpdateVideoScrub(point);
        if (videoControlsHovered_ != previousHovered || VideoVolumeContains(point) != volumeWasHot)
            InvalidateRect(window_, nullptr, FALSE);
    }
    void VideoControlsMouseLeave() {
        if (!VideoActive()) return;
        videoControlsPointerOver_ = false;
        videoControlsHovered_ = ButtonKind::None;
        SetVideoPlaybackSpeedHover(-1);
        SetVideoFullscreenGlyphHover(false);
        if (VideoUserPlaybackActive() && !videoScrubbing_ && !videoVolumeDragging_ && !videoAdjustmentsOriginalPreviewActive_ && !videoPlaybackSpeedPanelOpen_) {
            videoControlsFadeActive_ = false;
            videoControlsLastActivity_ = GetTickCount64();
            SetTimer(window_, kVideoControlsTimer, static_cast<UINT>(kVideoControlsIdleDelayMs), nullptr);
        }
    }
    void CancelVideoControlsInteraction() {
        StopVideoStepHold();
        videoAdjustmentsDragging_ = -1;
        videoAdjustmentThumbGrab_ = false;
        videoVolumeDragging_ = false;
        videoVolumeThumbGrab_ = false;
        videoScrubberThumbGrab_ = false;
        SetVideoAdjustmentsOriginalPreview(false);
        if (!videoScrubbing_) return;
        videoScrubbing_ = false;
        const bool resumePlayback = videoWasPlayingBeforeScrub_;
        videoWasPlayingBeforeScrub_ = false;
        if (resumePlayback && VideoActive() && !videoPlayer_.Playing()) ToggleVideoPlayPause();
        else ShowVideoControls();
    }
    void SetVideoFullscreenGlyphHover(bool hovered) {
        const float target = hovered != fullscreen_ ? 1.0f : 0.0f;
        if (std::abs(videoFullscreenGlyphHoverTarget_ - target) < 0.001f) return;
        UpdateVideoFullscreenGlyphHover();
        videoFullscreenGlyphHoverStart_ = videoFullscreenGlyphHoverProgress_;
        videoFullscreenGlyphHoverTarget_ = target;
        videoFullscreenGlyphHoverStartedAt_ = GetTickCount64();
        if (std::abs(videoFullscreenGlyphHoverStart_ - target) < 0.001f) {
            videoFullscreenGlyphHoverProgress_ = target;
            KillTimer(window_, kVideoFullscreenGlyphTimer);
        } else SetTimer(window_, kVideoFullscreenGlyphTimer, 16, nullptr);
        InvalidateRect(window_, nullptr, FALSE);
    }
    void UpdateVideoFullscreenGlyphHover() {
        const float elapsed = static_cast<float>(GetTickCount64() - videoFullscreenGlyphHoverStartedAt_);
        const float progress = std::clamp(elapsed / static_cast<float>(kVideoFullscreenGlyphDurationMs), 0.0f, 1.0f);
        videoFullscreenGlyphHoverProgress_ = videoFullscreenGlyphHoverStart_ +
            (videoFullscreenGlyphHoverTarget_ - videoFullscreenGlyphHoverStart_) * SmoothTransitionProgress(progress);
        InvalidateRect(window_, nullptr, FALSE);
        if (progress < 1.0f) SetTimer(window_, kVideoFullscreenGlyphTimer, 16, nullptr);
        else KillTimer(window_, kVideoFullscreenGlyphTimer);
    }
    void UpdateVideoControlsFade() {
        if (!VideoActive()) { StopVideoControls(); return; }
        if (!VideoUserPlaybackActive() || videoControlsPointerOver_ || videoScrubbing_ || videoVolumeDragging_ || videoAdjustmentsOriginalPreviewActive_ || videoPlaybackSpeedPanelOpen_) { KillTimer(window_, kVideoControlsTimer); return; }
        const ULONGLONG elapsed = GetTickCount64() - videoControlsLastActivity_;
        if (!videoControlsFadeActive_) {
            if (elapsed < kVideoControlsIdleDelayMs) {
                SetTimer(window_, kVideoControlsTimer, static_cast<UINT>(kVideoControlsIdleDelayMs - elapsed), nullptr);
                return;
            }
            videoControlsFadeActive_ = true;
            videoControlsFadeStart_ = GetTickCount64();
            videoControlsFadeStartOpacity_ = videoControlsOpacity_;
        }
        const float progress = std::min(1.0f, static_cast<float>(GetTickCount64() - videoControlsFadeStart_) / static_cast<float>(kVideoControlsFadeDurationMs));
        videoControlsOpacity_ = videoControlsFadeStartOpacity_ * (1.0f - progress);
        InvalidateRect(window_, nullptr, FALSE);
        if (progress < 1.0f) SetTimer(window_, kVideoControlsTimer, 16, nullptr);
        else {
            videoControlsFadeActive_ = false;
            KillTimer(window_, kVideoControlsTimer);
            SynchronizeVideoAdjustmentsPanelPresentedLayout(true);
            HideVideoCursorIfAppropriate();
        }
    }
    void UpdateTriangleCountTooltipHover(POINT point) {
        const RECT textBounds = TriangleCountTitleTextBounds();
        const bool hovering = TriangleCountTooltipAvailable() && PtInRect(&textBounds, point);
        if (triangleCountTooltipHovering_ == hovering) return;
        triangleCountTooltipHovering_ = hovering;
        if (!hovering) {
            DismissTriangleCountTooltip();
            return;
        }
        SetTimer(window_, kTriangleCountTooltipTimer, kTriangleCountTooltipDelayMs, nullptr);
    }
    void TriangleCountTooltipTimerMessage() {
        KillTimer(window_, kTriangleCountTooltipTimer);
        if (!triangleCountTooltipHovering_ || !TriangleCountTooltipAvailable()) return;
        triangleCountTooltipVisible_ = true;
        InvalidateRect(window_, nullptr, FALSE);
    }
