    bool CommitBuildPlateSize(bool width) { wchar_t* end=nullptr; const float value=std::wcstof(buildPlateSizeText_.c_str(),&end); if(end==buildPlateSizeText_.c_str()||*end||!std::isfinite(value)||value<50||value>5000)return false; if(width)modelBuildPlateWidthMm_=value;else modelBuildPlateDepthMm_=value;if(buildPlateSizeLinked_){modelBuildPlateWidthMm_=modelBuildPlateDepthMm_=value;}WriteSetting(L"ModelBuildPlateWidthMm",DWORD(std::lround(modelBuildPlateWidthMm_)));WriteSetting(L"ModelBuildPlateDepthMm",DWORD(std::lround(modelBuildPlateDepthMm_)));if(ModelActive())modelViewport_.SetBuildPlate(BuildPlateVisible(),ModelUpVector(),modelBuildPlateWidthMm_,modelBuildPlateDepthMm_);InvalidateRect(window_,nullptr,FALSE);return true; }
    void CommitActiveBuildPlateSize() { if(!buildPlateSizeEdit_)return; CommitBuildPlateSize(buildPlateSizeEdit_==1); buildPlateSizeEdit_=0; buildPlateSizeReplace_=false; InvalidateRect(window_,nullptr,FALSE); }
    void FocusBuildPlateSize(int edit) { if(buildPlateSizeEdit_&&buildPlateSizeEdit_!=edit)CommitActiveBuildPlateSize();buildPlateSizeEdit_=edit;buildPlateSizeReplace_=true;buildPlateSizeText_=std::to_wstring(int(std::lround(edit==1?modelBuildPlateWidthMm_:modelBuildPlateDepthMm_)));InvalidateRect(window_,nullptr,FALSE); }
    void CancelBuildPlateSizeEdit() { buildPlateSizeEdit_=0;buildPlateSizeReplace_=false;buildPlateSizeText_.clear(); }
    void NavigateBuildPlateSize(bool reverse) { const int next=buildPlateSizeEdit_==0?(reverse?2:1):buildPlateSizeEdit_==1?2:1;FocusBuildPlateSize(next); }
    void BuildPlateSizeChar(wchar_t character) { if(!buildPlateSizeEdit_)return; if(character==L'\b'){buildPlateSizeReplace_=false;if(!buildPlateSizeText_.empty())buildPlateSizeText_.pop_back();}else if(character>=L'0'&&character<=L'9'){if(buildPlateSizeReplace_){buildPlateSizeText_.clear();buildPlateSizeReplace_=false;}if(buildPlateSizeText_.size()<4)buildPlateSizeText_+=character;}else if(character==L'\r'){CommitActiveBuildPlateSize();}InvalidateRect(window_,nullptr,FALSE); }
